'use client';

import { useEffect, useRef, useState, useCallback } from 'react';
import { useSettingsStore } from '@/store/settingsStore';
import {
  startPoseTracker,
  isPoseTrackingSupported,
  type PoseTrackerHandle,
  type TrackingTarget,
} from '@/services/bodyPoseService';
import { tapFeedback } from '@/services/feedback';

/**
 * Camera Input Overlay — opt-in camera-based finger/arm tracking.
 *
 * Uses MediaPipe Pose to detect the user's finger/arm position via
 * the webcam and maps it to cursor position on screen.
 *
 * DISABLED BY DEFAULT (settingsStore.cameraInputEnabled = false).
 * Users opt in via Settings → Input modes. The accuracy regression in
 * v0.2.x made the overlay interfere with mouse use; we force-disable
 * on migration to v9 and let users re-enable explicitly.
 *
 * Tracking targets: right_wrist (default), right_index, left_index,
 * left_wrist, right_elbow, left_elbow, nose, etc.
 */

type Status = 'starting' | 'tracking' | 'lost' | 'stopped';

export default function CameraInputOverlay() {
  const enabled = useSettingsStore(s => s.cameraInputEnabled);
  const target = useSettingsStore(s => s.cameraTrackingTarget) as TrackingTarget;
  const dwellMs = useSettingsStore(s => s.headTrackingDwellMs);
  const sensitivity = useSettingsStore(s => s.headTrackingSensitivity);

  const [status, setStatus] = useState<Status>('stopped');
  const [activeTarget, setActiveTarget] = useState(target);
  const [cursorPos, setCursorPos] = useState({ x: -100, y: -100 });
  const [dwellProgress, setDwellProgress] = useState(0);

  const handleRef = useRef<PoseTrackerHandle | null>(null);
  const dwellStartRef = useRef(0);
  const dwellElementRef = useRef<Element | null>(null);
  const rafRef = useRef(0);
  const highlightedKeyRef = useRef<HTMLElement | null>(null);
  const [keyBubble, setKeyBubble] = useState<{ char: string; x: number; y: number; visible: boolean }>({ char: '', x: 0, y: 0, visible: false });

  const animateDwell = useCallback(() => {
    if (!dwellElementRef.current || dwellStartRef.current === 0) {
      setDwellProgress(0);
      return;
    }
    const progress = Math.min(1, (Date.now() - dwellStartRef.current) / dwellMs);
    setDwellProgress(progress);
    if (progress < 1) rafRef.current = requestAnimationFrame(animateDwell);
  }, [dwellMs]);

  useEffect(() => {
    if (!enabled || !isPoseTrackingSupported()) {
      if (handleRef.current) { handleRef.current.stop(); handleRef.current = null; }
      setStatus('stopped');
      return;
    }

    const handle = startPoseTracker({
      dwellMs,
      sensitivity,
      smoothing: 0.15,
      trackingTarget: target,
      cursorSmoothing: 0.12,
      onMove(x, y) {
        setCursorPos({ x, y });

        // Proximity detection is fed by real landmark data from the pose
        // tracker (not here — CameraInputOverlay only receives cursor x,y).
        // Proximity click will be wired when bodyPoseService provides
        // finger width data alongside cursor position.

        const el = document.elementFromPoint(x, y);
        const interactive = el?.closest('button, a, [role="button"], [data-dwell-target], .aac-btn') ?? null;

        const keyBtn = el?.closest('button[data-key], button[data-action]') as HTMLElement | null;
        if (keyBtn && keyBtn !== highlightedKeyRef.current) {
          highlightedKeyRef.current?.classList.remove('camera-cursor-highlight');
          highlightedKeyRef.current = keyBtn;
          keyBtn.classList.add('camera-cursor-highlight');
          const char = keyBtn.getAttribute('data-display') || '';
          const isUtility = !!keyBtn.getAttribute('data-action');
          if (char && !isUtility && char.length <= 2) {
            const rect = keyBtn.getBoundingClientRect();
            setKeyBubble({ char, x: rect.left + rect.width / 2, y: rect.top, visible: true });
          } else {
            setKeyBubble(prev => ({ ...prev, visible: false }));
          }
        } else if (!keyBtn && highlightedKeyRef.current) {
          highlightedKeyRef.current.classList.remove('camera-cursor-highlight');
          highlightedKeyRef.current = null;
          setKeyBubble(prev => ({ ...prev, visible: false }));
        }

        if (interactive) {
          if (interactive !== dwellElementRef.current) {
            dwellElementRef.current = interactive;
            dwellStartRef.current = Date.now();
            cancelAnimationFrame(rafRef.current);
            rafRef.current = requestAnimationFrame(animateDwell);
          }
        } else {
          dwellElementRef.current = null;
          dwellStartRef.current = 0;
          setDwellProgress(0);
          cancelAnimationFrame(rafRef.current);
        }
      },
      onDwell() {
        tapFeedback();
        setDwellProgress(0);
        dwellElementRef.current = null;
        dwellStartRef.current = 0;
      },
      onStatusChange(s, detectedTarget) {
        setStatus(s);
        if (detectedTarget) setActiveTarget(detectedTarget);
      },
    });

    handleRef.current = handle;

    return () => {
      cancelAnimationFrame(rafRef.current);
      highlightedKeyRef.current?.classList.remove('camera-cursor-highlight');
      highlightedKeyRef.current = null;
      handle.stop();
      handleRef.current = null;
    };
  }, [enabled, target, dwellMs, sensitivity, animateDwell]);

  // Pointer fallback: when camera is on but can't detect the target
  // (MacBook — hands below FOV), use mouse movement for cursor + highlights.
  // Uses a ref to avoid stale closure over status.
  const statusRef = useRef(status);
  statusRef.current = status;

  useEffect(() => {
    if (!enabled) return;
    const onMove = (e: MouseEvent) => {
      if (statusRef.current === 'tracking') return;
      setCursorPos({ x: e.clientX, y: e.clientY });

      const el = document.elementFromPoint(e.clientX, e.clientY);
      const keyBtn = el?.closest('button[data-key], button[data-action]') as HTMLElement | null;
      if (keyBtn && keyBtn !== highlightedKeyRef.current) {
        highlightedKeyRef.current?.classList.remove('camera-cursor-highlight');
        highlightedKeyRef.current = keyBtn;
        keyBtn.classList.add('camera-cursor-highlight');
      } else if (!keyBtn && highlightedKeyRef.current) {
        highlightedKeyRef.current.classList.remove('camera-cursor-highlight');
        highlightedKeyRef.current = null;
      }
      // No bubble for mouse — mouse users click directly. Bubble is for camera dwell only.
      setKeyBubble(prev => prev.visible ? { ...prev, visible: false } : prev);
    };
    window.addEventListener('mousemove', onMove);
    return () => window.removeEventListener('mousemove', onMove);
  }, [enabled]);

  if (!enabled) return null;

  const statusColor = status === 'tracking' ? '#4CAF50' : status === 'lost' ? '#FF9800' : '#2196F3';
  const bubbleY = keyBubble.visible ? Math.max(5, keyBubble.y - 55) : 0;
  const bubbleX = keyBubble.visible ? Math.max(25, Math.min(typeof window !== 'undefined' ? window.innerWidth - 25 : 9999, keyBubble.x)) : 0;

  return (
    <div className="fixed inset-0 pointer-events-none" style={{ zIndex: 9998 }} aria-hidden="true">
      {/* Precision bubble on keyboard key */}
      {keyBubble.visible && (
        <div className="precision-bubble" style={{ left: bubbleX, top: bubbleY, pointerEvents: 'none' }}>
          {keyBubble.char}
        </div>
      )}
      {/* Cursor dot — only for camera tracking, not mouse fallback */}
      {status === 'tracking' && cursorPos.x > 0 && cursorPos.y > 0 && <div
        style={{
          position: 'absolute',
          left: cursorPos.x - 14,
          top: cursorPos.y - 14,
          width: 28,
          height: 28,
          borderRadius: '50%',
          backgroundColor: statusColor,
          opacity: 0.85,
          border: '2px solid white',
          boxShadow: `0 0 12px ${statusColor}80`,
          transition: 'left 0.06s linear, top 0.06s linear',
          pointerEvents: 'none',
        }}
      />}

      {/* Dwell ring */}
      {dwellProgress > 0 && (
        <svg
          width="50" height="50"
          style={{
            position: 'absolute',
            left: cursorPos.x - 25,
            top: cursorPos.y - 25,
            transition: 'left 0.06s linear, top 0.06s linear',
          }}
        >
          <circle cx="25" cy="25" r="22" fill="none" stroke="rgba(255,255,255,0.3)" strokeWidth="3" />
          <circle
            cx="25" cy="25" r="22"
            fill="none" stroke="#4CAF50" strokeWidth="4"
            strokeDasharray={Math.PI * 44}
            strokeDashoffset={Math.PI * 44 * (1 - dwellProgress)}
            strokeLinecap="round"
            transform="rotate(-90 25 25)"
          />
        </svg>
      )}

      {/* Status badge */}
      <div
        style={{
          position: 'absolute',
          bottom: 8,
          left: 8,
          display: 'flex',
          alignItems: 'center',
          gap: 5,
          background: 'rgba(0,0,0,0.5)',
          color: 'white',
          padding: '3px 10px',
          borderRadius: 16,
          fontSize: 11,
          fontWeight: 600,
        }}
      >
        <span style={{ width: 7, height: 7, borderRadius: '50%', backgroundColor: statusColor, display: 'inline-block' }} />
        {status === 'tracking' ? `Tracking ${activeTarget.replace('_', ' ')}` : status}
      </div>
    </div>
  );
}

'use client';
import { ReactNode } from 'react';
import { useUIStore } from '@/store/uiStore';
import { useMessageStore } from '@/store/messageStore';
import { useCategoryStore } from '@/store/categoryStore';
import { usePredictionStore } from '@/store/predictionStore';
import { tapFeedback } from '@/services/feedback';
import { useSettingsStore, GridSize } from '@/store/settingsStore';
import { aacSpeak } from '@/services/aacSpeak';
import { classifyWord, CATEGORY_COLORS } from '@/engine/colorCoding';
import { useT } from '@/engine/useT';
import PhraseTile from './PhraseTile';
import { getPhraseText } from '@/constants/phraseTranslations';

/**
 * Category / Math / Ordering panel — renders inline, docked above the
 * keyboard. The panel claims roughly the upper half of the viewport (it is
 * `flex-1` next to a `flex-1` keyboard wrapper) so the user keeps typing on
 * the same soft keyboard, can hear the same predictions, and never has the
 * panel cover the keys. This mirrors the AI Chat layout.
 */
function PanelShell({ children }: { children: ReactNode }) {
  const { t: pt, outputTtsCode: ptOut } = useT();
  return (
    <section
      aria-label={pt('aac_panel')}
      className="flex-[3] min-h-0 flex flex-col surface-bar border-y border-theme"
    >
      {children}
    </section>
  );
}

const GRID_COLS: Record<GridSize, string> = {
  4:  'grid-cols-2',
  6:  'grid-cols-2 md:grid-cols-3',
  9:  'grid-cols-3',
  12: 'grid-cols-3 md:grid-cols-4',
  16: 'grid-cols-4',
  20: 'grid-cols-4 md:grid-cols-5',
};

const TILE_MIN_H: Record<GridSize, string> = {
  4:  'min-h-[clamp(120px,22vw,180px)]',
  6:  'min-h-[clamp(100px,18vw,150px)]',
  9:  'min-h-[clamp(80px,15vw,120px)]',
  12: 'min-h-[clamp(70px,12vw,100px)]',
  16: 'min-h-[clamp(60px,10vw,90px)]',
  20: 'min-h-[clamp(50px,8vw,80px)]',
};

export default function CategoryPanel() {
  const { t, ttsCode, outputTtsCode } = useT();
  const {
    sidePanel, activeCategoryId, activeSequenceId, activeSequenceStep,
    closeSidePanel, selectCategory, backToCategories, startOrdering, nextStep, prevStep, finishOrdering,
  } = useUIStore();
  const { appendText, text, autoSpeak, soundEnabled } = useMessageStore();
  const { allCategories, getPhrasesForCategory, getSequencesForCategory } = useCategoryStore();
  const { learnWord } = usePredictionStore();
  const gridSize = useSettingsStore((s) => s.gridSize);
  const language = useSettingsStore((s) => s.language);
  const { speechRate, speechVolume } = useSettingsStore();

  const isOpen =
    sidePanel === 'categories' ||
    sidePanel === 'category-detail' ||
    sidePanel === 'ordering';

  if (!isOpen) return null;

  const handlePhrase = (phraseText: string) => {
    tapFeedback();
    const existingWords = text.trim().split(/\s+/).filter(Boolean);
    const prevWord = existingWords.length > 0 ? existingWords[existingWords.length - 1] : undefined;
    const prevPrevWord = existingWords.length > 1 ? existingWords[existingWords.length - 2] : undefined;
    appendText(phraseText);
    const phraseWords = phraseText.trim().split(/\s+/);
    let prev = prevWord;
    let prevPrev = prevPrevWord;
    for (const w of phraseWords) {
      learnWord(w.toLowerCase(), prev?.toLowerCase(), prevPrev?.toLowerCase());
      prevPrev = prev;
      prev = w;
    }
    if (autoSpeak && soundEnabled) aacSpeak(phraseText, speechRate, speechVolume);
  };

  const btn = 'aac-btn surface-key text-primary rounded-xl p-3 font-bold text-xl md:text-2xl select-none text-center border border-theme';
  const closeBtn = 'aac-btn w-12 h-12 rounded-xl surface-key text-muted text-2xl flex items-center justify-center border border-theme';
  const headerRow = 'flex items-center justify-between px-4 py-3 border-b border-theme shrink-0';
  const headerTitle = 'text-primary font-bold text-2xl md:text-3xl';

  // ── ORDERING FLOW ───────────────────────────────────────────────────────
  if (sidePanel === 'ordering' && activeSequenceId) {
    const allSeqs = getSequencesForCategory(activeCategoryId ?? '');
    const seq = allSeqs.find((s) => s.id === activeSequenceId);
    if (!seq) return null;
    const step = seq.steps[activeSequenceStep];
    if (!step) return null;
    return (
      <PanelShell>
        <div className={headerRow}>
          <button onClick={() => { tapFeedback(); backToCategories(); }} aria-label={t('back_to_categories')} className="aac-btn h-12 px-4 rounded-xl surface-key text-muted text-lg flex items-center justify-center border border-theme">← {t('previous_step')}</button>
          <span className={headerTitle}>{seq.name}</span>
          <span className="text-muted text-lg">{activeSequenceStep + 1}/{seq.steps.length}</span>
        </div>
        <div className="p-4 flex-1 overflow-y-auto min-h-0">
          <p className="text-primary font-bold text-center mb-3 text-2xl md:text-3xl">{step.label}</p>
          <div className="flex flex-col gap-2">
            {step.options.map((opt) => {
              const localOpt = getPhraseText(opt.id, language, opt.text);
              return (
                <button key={opt.id} onClick={() => handlePhrase(localOpt)} aria-label={localOpt} className={`${btn} text-left`}>
                  {localOpt}
                </button>
              );
            })}
          </div>
        </div>
        <div className="flex gap-2 p-3 border-t border-theme shrink-0">
          <button onClick={prevStep} disabled={activeSequenceStep === 0} aria-label={t('previous_step')} className={`${btn} flex-1 ${activeSequenceStep === 0 ? 'opacity-30' : ''}`}>← {t('prev')}</button>
          {activeSequenceStep < seq.steps.length - 1 ? (
            <button onClick={() => nextStep(seq.steps.length)} aria-label={t('next_step')} className={`${btn} flex-1`}>{t('next_step')} →</button>
          ) : (
            <button onClick={finishOrdering} aria-label={t('done')} className={`${btn} flex-1 bg-[#4CAF50] text-white border-transparent`}>{t('done')} ✓</button>
          )}
        </div>
      </PanelShell>
    );
  }

  // ── CATEGORY DETAIL ─────────────────────────────────────────────────────
  if (sidePanel === 'category-detail' && activeCategoryId) {
    const categories = allCategories();
    const cat = categories.find((c) => c.id === activeCategoryId);
    const phrases = getPhrasesForCategory(activeCategoryId);
    const sequences = getSequencesForCategory(activeCategoryId);
    return (
      <PanelShell>
        <div className={headerRow}>
          <button onClick={backToCategories} className="aac-btn h-12 px-4 rounded-xl surface-key text-muted text-lg flex items-center justify-center border border-theme">← {t('previous_step')}</button>
          <span className={headerTitle}>{cat?.icon} {cat?.nameKey ? t(cat.nameKey) : cat?.name}</span>
          <button onClick={() => { tapFeedback(); closeSidePanel(); }} aria-label={t('close_panel')} className={closeBtn}>✕</button>
        </div>
        {sequences.length > 0 && (
          <div className="flex gap-2 p-3 border-b border-theme shrink-0">
            {sequences.map((seq) => (
              <button key={seq.id} onClick={() => startOrdering(seq.id)} className={`${btn} flex-1`}>🛒 {seq.name}</button>
            ))}
          </div>
        )}
        <div className={`grid ${GRID_COLS[gridSize]} gap-2 p-3 overflow-y-auto flex-1 min-h-0`}>
          {phrases.map((p) => {
            const localText = getPhraseText(p.id, language, p.text);
            const firstWord = p.text.split(/\s+/)[0];
            const color = CATEGORY_COLORS[classifyWord(firstWord)];
            return (
              <PhraseTile
                key={p.id}
                phrase={localText}
                englishPhrase={p.text}
                onClick={() => handlePhrase(localText)}
                className={`${btn} ${TILE_MIN_H[gridSize]}`}
                style={{ borderLeftColor: color, borderLeftWidth: '5px' }}
              />
            );
          })}
        </div>
      </PanelShell>
    );
  }

  // ── CATEGORY LIST ───────────────────────────────────────────────────────
  const categories = allCategories();
  return (
    <PanelShell>
      <div className={headerRow}>
        <span className={headerTitle}>{t('categories')}</span>
        <button onClick={() => { tapFeedback(); closeSidePanel(); }} aria-label={t('close_panel')} className={closeBtn}>✕</button>
      </div>
      <div className={`grid ${GRID_COLS[gridSize]} gap-2 p-3 overflow-y-auto flex-1 min-h-0`}>
        {categories.map((cat) => (
          <button
            key={cat.id}
            onClick={() => selectCategory(cat.id)}
            className={`${btn} flex items-center gap-3 text-left ${TILE_MIN_H[gridSize]}`}
          >
            <span className="text-3xl md:text-4xl">{cat.icon}</span>
            <span>{cat.nameKey ? t(cat.nameKey) : cat.name}</span>
          </button>
        ))}
      </div>
    </PanelShell>
  );
}

