  apple:  { en: 'apple', es: 'manzana', fr: 'pomme', de: 'Apfel', pt: 'maçã', ro: 'măr', uk: 'яблуко', ru: 'яблоко', ja: 'りんご', ko: '사과', zh: '苹果', ar: 'تفاحة' },
