          className="ml-3 text-2xl"
        >🔊</button>
      </div>

      <div className="flex-1 flex flex-col gap-3 p-4 overflow-y-auto" style={{ background: 'linear-gradient(180deg, #fda085 0%, #f6d365 50%, #ffecd2 100%)' }}>
