'use client';

import { useEffect, useRef, useState, useCallback } from 'react';
import { useSettingsStore } from '@/store/settingsStore';
import {
  startHeadTracker,
  isHeadTrackingSupported,
  type HeadTrackerHandle,
} from '@/services/headTracker';
import {
  createGestureDetector,
  destroyGestureDetector,
  type GestureDetector,
} from '@/services/gestureService';
import { tapFeedback } from '@/services/feedback';
import { useT } from '@/engine/useT';

/* ─────────────────────────────────────────────────────────────────────────────
 *  HeadTrackingOverlay
 *
 *  Renders above all other content when head tracking is enabled:
 *    - Cursor dot (20px circle) following head position
 *    - Dwell progress ring around cursor
 *    - Highlight border on element under cursor
 *    - Camera PIP preview (80x60px corner)
 *    - Status indicator
 * ────────────────────────────────────────────────────────────────────────── */

type TrackingStatus = 'starting' | 'tracking' | 'lost' | 'stopped';

export default function HeadTrackingOverlay() {
  const enabled = useSettingsStore((s) => s.headTrackingEnabled);
  const dwellMs = useSettingsStore((s) => s.headTrackingDwellMs);
  const sensitivity = useSettingsStore((s) => s.headTrackingSensitivity);
  const gestureConfig = useSettingsStore((s) => s.gestureConfig);

  const { t } = useT();

  const [status, setStatus] = useState<TrackingStatus>('stopped');
  const [cursorPos, setCursorPos] = useState({ x: -100, y: -100 });
  const [dwellProgress, setDwellProgress] = useState(0);
  const [highlightRect, setHighlightRect] = useState<DOMRect | null>(null);

  const handleRef = useRef<HeadTrackerHandle | null>(null);
  const gestureDetectorRef = useRef<GestureDetector | null>(null);
  const pipVideoRef = useRef<HTMLVideoElement | null>(null);
  const dwellStartRef = useRef(0);
  const dwellElementRef = useRef<Element | null>(null);
  const rafDwellRef = useRef(0);

  // Dwell progress animation
  const animateDwellProgress = useCallback(() => {
    if (!dwellElementRef.current || dwellStartRef.current === 0) {
      setDwellProgress(0);
      return;
    }
    const elapsed = Date.now() - dwellStartRef.current;
    const progress = Math.min(1, elapsed / dwellMs);
    setDwellProgress(progress);
    if (progress < 1) {
      rafDwellRef.current = requestAnimationFrame(animateDwellProgress);
    }
  }, [dwellMs]);

  // Start / stop tracker based on enabled flag
  useEffect(() => {
    if (!enabled || !isHeadTrackingSupported()) {
      if (handleRef.current) { handleRef.current.stop(); handleRef.current = null; }
      setStatus('stopped');
      return;
    }

    // Create gesture detector if gesture recognition is enabled
    if (gestureConfig.enabled) {
      gestureDetectorRef.current = createGestureDetector(gestureConfig, (event) => {
        const mapping = gestureConfig.mappings.find(m => m.gesture === event.gesture);
        if (mapping) {
          // Execute the mapped action — trigger a click on the matching button
          const target = document.querySelector(`[data-action="${mapping.action}"], [data-key="${mapping.action}"], #${mapping.action}`);
          if (target instanceof HTMLElement) {
            tapFeedback();
            target.click();
          }
        }
      });
    }

    const handle = startHeadTracker({
      dwellMs,
      sensitivity,
      smoothing: 0.15,
      onLandmarks: gestureConfig.enabled ? (data) => {
        gestureDetectorRef.current?.processFrame(data);
      } : undefined,
      onMove(x, y) {
        setCursorPos({ x, y });

        // Track which element is under cursor for highlight
        const el = document.elementFromPoint(x, y);
        const interactive = el?.closest('button, a, [role="button"], [data-dwell-target], .aac-btn') ?? null;
        if (interactive) {
          const rect = interactive.getBoundingClientRect();
          setHighlightRect(rect);
          if (interactive !== dwellElementRef.current) {
            dwellElementRef.current = interactive;
            dwellStartRef.current = Date.now();
            cancelAnimationFrame(rafDwellRef.current);
            rafDwellRef.current = requestAnimationFrame(animateDwellProgress);
          }
        } else {
          setHighlightRect(null);
          dwellElementRef.current = null;
          dwellStartRef.current = 0;
          setDwellProgress(0);
          cancelAnimationFrame(rafDwellRef.current);
        }
      },
      onDwell(_element) {
        tapFeedback();
        setDwellProgress(0);
        dwellElementRef.current = null;
        dwellStartRef.current = 0;
      },
      onStatusChange(s) {
        setStatus(s);
      },
    });

    handleRef.current = handle;

    // Set up PIP preview: clone the video stream into a small visible element
    const checkVideo = setInterval(() => {
      if (handle.videoElement && handle.videoElement.srcObject && pipVideoRef.current) {
        pipVideoRef.current.srcObject = handle.videoElement.srcObject;
        pipVideoRef.current.play().catch(() => {});
        clearInterval(checkVideo);
      }
    }, 200);

    return () => {
      clearInterval(checkVideo);
      cancelAnimationFrame(rafDwellRef.current);
      handle.stop();
      handleRef.current = null;
      destroyGestureDetector();
      gestureDetectorRef.current = null;
    };
    // Re-create tracker when key settings change
  }, [enabled, dwellMs, sensitivity, gestureConfig, animateDwellProgress]);

  if (!enabled) return null;

  const statusLabel =
    status === 'starting' ? t('starting') :
    status === 'tracking' ? t('tracking') :
    status === 'lost' ? t('face_lost') :
    t('stopped');

  const statusColor =
    status === 'tracking' ? '#4CAF50' :
    status === 'lost' ? '#FF9800' :
    status === 'starting' ? '#2196F3' :
    '#999';

  // SVG dwell ring
  const ringRadius = 16;
  const ringCircumference = 2 * Math.PI * ringRadius;
  const ringOffset = ringCircumference * (1 - dwellProgress);

  return (
    <div
      className="fixed inset-0 pointer-events-none"
      style={{ zIndex: 9999 }}
      aria-hidden="true"
    >
      {/* ── Cursor dot + dwell ring — large and visible ── */}
      <div
        style={{
          position: 'absolute',
          left: cursorPos.x - 40,
          top: cursorPos.y - 40,
          width: 80,
          height: 80,
          transition: 'left 0.06s linear, top 0.06s linear',
        }}
      >
        {/* Dwell progress ring */}
        <svg width="80" height="80" style={{ position: 'absolute', top: 0, left: 0 }}>
          <circle cx="40" cy="40" r="35" fill="none" stroke="rgba(255,255,255,0.3)" strokeWidth="4" />
          {dwellProgress > 0 && (
            <circle
              cx="40" cy="40" r="35"
              fill="none"
              stroke="#4CAF50"
              strokeWidth="5"
              strokeDasharray={Math.PI * 70}
              strokeDashoffset={Math.PI * 70 * (1 - dwellProgress)}
              strokeLinecap="round"
              transform="rotate(-90 40 40)"
            />
          )}
        </svg>
        {/* Cursor dot — 36px, bright, with glow */}
        <div
          style={{
            position: 'absolute',
            left: 22,
            top: 22,
            width: 36,
            height: 36,
            borderRadius: '50%',
            backgroundColor: status === 'tracking' ? '#4CAF50' : '#FF9800',
            opacity: 0.9,
            boxShadow: `0 0 20px ${status === 'tracking' ? 'rgba(76,175,80,0.6)' : 'rgba(255,152,0,0.6)'}, 0 0 40px ${status === 'tracking' ? 'rgba(76,175,80,0.3)' : 'rgba(255,152,0,0.3)'}`,
            border: '3px solid white',
            animation: dwellProgress > 0 ? 'none' : 'pulse-cursor 2s ease-in-out infinite',
          }}
        />
      </div>

      {/* ── Highlight border on interactive element ── */}
      {highlightRect && (
        <div
          style={{
            position: 'absolute',
            left: highlightRect.left - 3,
            top: highlightRect.top - 3,
            width: highlightRect.width + 6,
            height: highlightRect.height + 6,
            border: '3px solid #4CAF50',
            borderRadius: 8,
            transition: 'all 0.1s ease',
          }}
        />
      )}

      {/* ── Status indicator (top-center) ── */}
      <div
        style={{
          position: 'absolute',
          top: 4,
          left: '50%',
          transform: 'translateX(-50%)',
          display: 'flex',
          alignItems: 'center',
          gap: 6,
          background: 'rgba(0,0,0,0.6)',
          color: 'white',
          padding: '4px 12px',
          borderRadius: 20,
          fontSize: 12,
          fontWeight: 600,
        }}
      >
        <span
          style={{
            width: 8, height: 8, borderRadius: '50%',
            backgroundColor: statusColor,
            display: 'inline-block',
          }}
        />
        {statusLabel}
      </div>

      {/* ── Camera PIP preview (bottom-right corner) ── */}
      <div
        style={{
          position: 'absolute',
          bottom: 8,
          right: 8,
          width: 80,
          height: 60,
          borderRadius: 8,
          overflow: 'hidden',
          border: '2px solid rgba(255,255,255,0.5)',
          backgroundColor: '#000',
        }}
      >
        <video
          ref={pipVideoRef}
          muted
          playsInline
          style={{
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            transform: 'scaleX(-1)', // mirror for natural feel
          }}
        />
      </div>
    </div>
  );
}

'use client';
import { useState, useCallback, useEffect, useRef } from 'react';
import { useSettingsStore } from '@/store/settingsStore';
import { tapFeedback } from '@/services/feedback';
import { useT } from '@/engine/useT';
import TrackingSetupWizard from './TrackingSetupWizard';
import { DEFAULT_GESTURE_CONFIG, type GestureId, type GestureMapping, type GestureConfig } from '@/services/gestureService';

const TRACKING_TARGETS = [
  { id: 'right_index', label: 'Right Index Finger' },
  { id: 'left_index', label: 'Left Index Finger' },
  { id: 'right_wrist', label: 'Right Wrist' },
  { id: 'left_wrist', label: 'Left Wrist' },
  { id: 'right_elbow', label: 'Right Elbow' },
  { id: 'left_elbow', label: 'Left Elbow' },
  { id: 'nose', label: 'Nose (Head)' },
  { id: 'right_shoulder', label: 'Right Shoulder' },
  { id: 'left_shoulder', label: 'Left Shoulder' },
];

function Toggle({ on, onToggle, label }: { on: boolean; onToggle: () => void; label: string }) {
  return (
    <button onClick={() => { tapFeedback(); onToggle(); }} aria-pressed={on} aria-label={label}
      className={`w-12 h-7 rounded-full transition-colors shrink-0 ${on ? 'bg-[#4CAF50]' : 'bg-[#999]'}`}>
      <div className={`w-5 h-5 rounded-full bg-white transition-transform mx-1 ${on ? 'translate-x-5' : ''}`} />
    </button>
  );
}

export default function InputModesSettings() {
  const [showSetupWizard, setShowSetupWizard] = useState(false);
  const cameraInputEnabled = useSettingsStore(s => s.cameraInputEnabled);
  const cameraTrackingTarget = useSettingsStore(s => s.cameraTrackingTarget);
  const showHandCalibration = useSettingsStore(s => s.showHandCalibration);
  const headTrackingEnabled = useSettingsStore(s => s.headTrackingEnabled);
  const headTrackingDwellMs = useSettingsStore(s => s.headTrackingDwellMs);
  const headTrackingSensitivity = useSettingsStore(s => s.headTrackingSensitivity);
  const update = useSettingsStore(s => s.update);
  const { t } = useT();

  return (
    <div className="space-y-4">
      {/* Camera Finger/Body Tracking (DEFAULT ON) */}
      <div>
        <h4 className="text-muted font-semibold text-sm uppercase tracking-wider mb-2">Camera Input (Default)</h4>
        <label className="flex items-center justify-between py-1.5">
          <div>
            <span className="text-primary text-sm font-semibold">Camera Finger Tracking</span>
            <p className="text-muted text-[10px]">Camera tracks your finger/arm and moves cursor on screen</p>
          </div>
          <Toggle on={cameraInputEnabled} onToggle={() => update({ cameraInputEnabled: !cameraInputEnabled })} label="Camera input" />
        </label>
        {cameraInputEnabled && (
          <div className="ml-2 mt-1 space-y-1">
            <label className="text-muted text-xs">Track:</label>
            <div className="grid grid-cols-3 gap-1">
              {TRACKING_TARGETS.map(tt => (
                <button key={tt.id} onClick={() => { tapFeedback(); update({ cameraTrackingTarget: tt.id }); }}
                  className={`aac-btn rounded-lg px-2 py-1.5 text-[10px] font-semibold border border-theme ${
                    cameraTrackingTarget === tt.id ? 'bg-[#4CAF50] text-white border-transparent' : 'surface-key text-primary'
                  }`}>
                  {tt.label}
                </button>
              ))}
            </div>
            <button
              onClick={() => { tapFeedback(); setShowSetupWizard(true); }}
              className="aac-btn w-full mt-2 py-2.5 rounded-xl text-white font-bold text-sm shadow-lg active:scale-95 transition-transform"
              style={{ background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' }}
            >
              🎯 Set Up Tracking
            </button>
            <p className="text-muted text-[10px] mt-1">Guided setup: detects your body, calibrates cursor, tests accuracy</p>
          </div>
        )}
      </div>

      {/* Hand Calibration visibility toggle */}
      <label className="flex items-center justify-between py-1.5">
        <div>
          <span className="text-primary text-sm font-semibold">Hand Calibration Settings</span>
          <p className="text-muted text-[10px]">Show hand profile + per-finger button mapping in Settings</p>
        </div>
        <Toggle on={showHandCalibration} onToggle={() => update({ showHandCalibration: !showHandCalibration })} label="Hand calibration settings" />
      </label>

      {/* Head Tracking (opt-in) */}
      <label className="flex items-center justify-between py-1.5">
        <div>
          <span className="text-primary text-sm font-semibold">{t('enable_head_tracking')}</span>
          <p className="text-muted text-[10px]">Move cursor by moving your head (uses camera)</p>
        </div>
        <Toggle on={headTrackingEnabled} onToggle={() => update({ headTrackingEnabled: !headTrackingEnabled })} label="Head tracking" />
      </label>

      {/* Dwell Time */}
      <div>
        <label className="flex items-center justify-between mb-1">
          <span className="text-primary text-sm">{t('dwell_time')}</span>
          <span className="text-muted text-sm">{headTrackingDwellMs}ms</span>
        </label>
        <input type="range" min="500" max="3000" step="100" value={headTrackingDwellMs}
          onChange={(e) => update({ headTrackingDwellMs: parseInt(e.target.value) })}
          className="w-full accent-[#4CAF50]" />
      </div>

      {/* Sensitivity */}
      <div>
        <label className="flex items-center justify-between mb-1">
          <span className="text-primary text-sm">{t('sensitivity')}</span>
          <span className="text-muted text-sm">{headTrackingSensitivity}</span>
        </label>
        <input type="range" min="1" max="10" step="1" value={headTrackingSensitivity}
          onChange={(e) => update({ headTrackingSensitivity: parseInt(e.target.value) })}
          className="w-full accent-[#2196F3]" />
      </div>
      {showSetupWizard && (
        <TrackingSetupWizard
          onComplete={() => setShowSetupWizard(false)}
          onCancel={() => setShowSetupWizard(false)}
        />
      )}

      {/* ─── Gesture Recognition ──────────────────────────────────────── */}
      <GestureRecognitionSettings />
    </div>
  );
}

// ── Built-in gestures for Basic mode (no training needed) ─────────────────

const BASIC_GESTURES: { id: GestureId; label: string; desc: string }[] = [
  { id: 'blink', label: 'Intentional Blink', desc: 'Close eyes for 400ms+' },
  { id: 'mouth_open', label: 'Mouth Open', desc: 'Open mouth wide (jaw drop)' },
  { id: 'smile', label: 'Smile', desc: 'Smile with either side of mouth' },
  { id: 'pucker', label: 'Pucker / "Oo"', desc: 'Push lips forward like saying "oo"' },
  { id: 'head_nod', label: 'Head Nod', desc: 'Nod head up and down' },
  { id: 'head_shake', label: 'Head Shake', desc: 'Shake head left and right' },
  { id: 'brow_raise', label: 'Eyebrow Raise', desc: 'Raise eyebrows up' },
];

const ASSIGNABLE_ACTIONS = [
  { value: '', label: '(not assigned)' },
  { value: 'speak', label: 'Speak message' },
  { value: 'backspace', label: 'Backspace' },
  { value: 'clear', label: 'Clear message' },
  { value: 'yes', label: 'Say "Yes"' },
  { value: 'no', label: 'Say "No"' },
  { value: 'help', label: 'Say "Help"' },
  { value: 'categories', label: 'Open Categories' },
  { value: 'settings', label: 'Open Settings' },
  { value: 'alert', label: 'Emergency Alert' },
  { value: 'ai_chat', label: 'Open AI Chat' },
];

function GestureRecognitionSettings() {
  const gestureConfig = useSettingsStore(s => s.gestureConfig);
  const update = useSettingsStore(s => s.update);
  const { t } = useT();

  const [calibrating, setCalibrating] = useState(false);
  const [calibrationProgress, setCalibrationProgress] = useState(0);

  const updateGesture = useCallback((partial: Partial<GestureConfig>) => {
    update({ gestureConfig: { ...gestureConfig, ...partial } });
  }, [gestureConfig, update]);

  const setMapping = useCallback((gestureId: GestureId, action: string) => {
    const existing = gestureConfig.mappings.filter(m => m.gesture !== gestureId);
    const next = action ? [...existing, { gesture: gestureId, action }] : existing;
    updateGesture({ mappings: next });
  }, [gestureConfig.mappings, updateGesture]);

  const getMappedAction = useCallback((gestureId: GestureId): string => {
    return gestureConfig.mappings.find(m => m.gesture === gestureId)?.action ?? '';
  }, [gestureConfig.mappings]);

  return (
    <div className="mt-4 pt-4 border-t border-theme">
      <h4 className="text-muted font-semibold text-sm uppercase tracking-wider mb-2">
        Gesture Recognition
      </h4>

      {/* Enable toggle */}
      <label className="flex items-center justify-between py-1.5">
        <div>
          <span className="text-primary text-sm font-semibold">Enable Gestures</span>
          <p className="text-muted text-[10px]">Detect head, eye, lip, and brow gestures via camera</p>
        </div>
        <Toggle
          on={gestureConfig.enabled}
          onToggle={() => updateGesture({ enabled: !gestureConfig.enabled })}
          label="Gesture recognition"
        />
      </label>

      {gestureConfig.enabled && (
        <div className="ml-2 mt-2 space-y-3">
          {/* Mode selector */}
          <div>
            <label className="text-muted text-xs mb-1 block">Mode</label>
            <div className="flex gap-1.5">
              <button
                onClick={() => { tapFeedback(); updateGesture({ mode: 'basic' }); }}
                className={`aac-btn flex-1 rounded-lg px-3 py-2 text-xs font-semibold border border-theme ${
                  gestureConfig.mode === 'basic' ? 'bg-[#4CAF50] text-white border-transparent' : 'surface-key text-primary'
                }`}
              >
                Basic
                <span className="block text-[9px] opacity-80 mt-0.5">No training needed</span>
              </button>
              <button
                onClick={() => { tapFeedback(); updateGesture({ mode: 'advanced' }); }}
                className={`aac-btn flex-1 rounded-lg px-3 py-2 text-xs font-semibold border border-theme ${
                  gestureConfig.mode === 'advanced' ? 'bg-[#9C27B0] text-white border-transparent' : 'surface-key text-primary'
                }`}
              >
                Advanced
                <span className="block text-[9px] opacity-80 mt-0.5">Custom training + 8B model</span>
              </button>
            </div>
          </div>

          {/* Baseline calibration */}
          <div>
            <button
              onClick={() => {
                tapFeedback();
                setCalibrating(true);
                setCalibrationProgress(0);
                const iv = setInterval(() => {
                  setCalibrationProgress(p => {
                    if (p >= 1) { clearInterval(iv); setCalibrating(false); return 1; }
                    return p + 1 / 45;
                  });
                }, 67);
              }}
              disabled={calibrating}
              className="aac-btn w-full py-2.5 rounded-xl text-white font-bold text-sm shadow-lg active:scale-95 transition-transform"
              style={{ background: calibrating ? '#999' : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' }}
            >
              {calibrating ? `Capturing neutral face... ${Math.round(calibrationProgress * 100)}%` : '🎯 Calibrate Neutral Face'}
            </button>
            <p className="text-muted text-[10px] mt-1">
              Hold still for 3 seconds. Sets your personal baseline so thresholds adapt to your face.
            </p>
          </div>

          {/* Gesture → Action assignment grid */}
          <div>
            <label className="text-muted text-xs mb-1.5 block">Assign gestures to actions</label>
            <div className="space-y-1.5">
              {BASIC_GESTURES.map(g => (
                <div key={g.id} className="flex items-center gap-2 px-2 py-1.5 rounded-lg surface-key border border-theme">
                  <div className="flex-1 min-w-0">
                    <span className="text-primary text-xs font-semibold block">{g.label}</span>
                    <span className="text-muted text-[9px]">{g.desc}</span>
                  </div>
                  <select
                    value={getMappedAction(g.id)}
                    onChange={e => { tapFeedback(); setMapping(g.id, e.target.value); }}
                    className="text-[11px] rounded-md border border-theme px-1.5 py-1 surface-key text-primary"
                  >
                    {ASSIGNABLE_ACTIONS.map(a => (
                      <option key={a.value} value={a.value}>{a.label}</option>
                    ))}
                  </select>
                </div>
              ))}
            </div>
          </div>

          {/* Sensitivity sliders */}
          <div>
            <label className="flex items-center justify-between mb-1">
              <span className="text-primary text-sm">Confidence threshold</span>
              <span className="text-muted text-sm">{Math.round(gestureConfig.confidenceThreshold * 100)}%</span>
            </label>
            <input
              type="range" min="30" max="95" step="5"
              value={Math.round(gestureConfig.confidenceThreshold * 100)}
              onChange={e => updateGesture({ confidenceThreshold: parseInt(e.target.value) / 100 })}
              className="w-full accent-[#4CAF50]"
            />
            <p className="text-muted text-[9px]">Lower = more sensitive (more false positives). Higher = stricter (may miss gestures).</p>
          </div>

          <div>
            <label className="flex items-center justify-between mb-1">
              <span className="text-primary text-sm">Cooldown</span>
              <span className="text-muted text-sm">{gestureConfig.cooldownMs}ms</span>
            </label>
            <input
              type="range" min="500" max="3000" step="100"
              value={gestureConfig.cooldownMs}
              onChange={e => updateGesture({ cooldownMs: parseInt(e.target.value) })}
              className="w-full accent-[#2196F3]"
            />
            <p className="text-muted text-[9px]">Minimum time between repeat triggers of the same gesture.</p>
          </div>

          <div>
            <label className="flex items-center justify-between mb-1">
              <span className="text-primary text-sm">Dwell time</span>
              <span className="text-muted text-sm">{gestureConfig.dwellMs}ms</span>
            </label>
            <input
              type="range" min="200" max="1000" step="50"
              value={gestureConfig.dwellMs}
              onChange={e => updateGesture({ dwellMs: parseInt(e.target.value) })}
              className="w-full accent-[#FF9800]"
            />
            <p className="text-muted text-[9px]">How long a gesture must be sustained before it triggers. Longer = fewer accidentals.</p>
          </div>

          {/* Advanced mode: training UI */}
          {gestureConfig.mode === 'advanced' && (
            <div className="mt-2 p-3 rounded-xl border border-[#9C27B0]/30 bg-[#9C27B0]/5">
              <h5 className="text-primary text-xs font-bold mb-1">Advanced Training</h5>
              <p className="text-muted text-[10px] mb-2">
                Record custom gestures and assign them to actions. The system learns your personal movement patterns using DTW template matching + 8B local model inference.
              </p>
              <p className="text-muted text-[10px]">
                {gestureConfig.templates.length === 0
                  ? 'No custom gestures recorded yet.'
                  : `${gestureConfig.templates.length} custom gesture(s) trained.`
                }
              </p>
              <button
                className="aac-btn w-full mt-2 py-2 rounded-lg text-[#9C27B0] font-bold text-xs border border-[#9C27B0]/30"
                onClick={() => {
                  tapFeedback();
                  alert('Custom gesture recording requires camera access. This feature will be available in the next update.');
                }}
              >
                + Record Custom Gesture
              </button>
            </div>
          )}

          {/* Reset */}
          <button
            onClick={() => { tapFeedback(); update({ gestureConfig: { ...DEFAULT_GESTURE_CONFIG } }); }}
            className="aac-btn w-full py-2 rounded-lg text-xs text-muted border border-theme surface-key"
          >
            Reset gestures to defaults
          </button>
        </div>
      )}
    </div>
  );
}

'use client';
import { useState, useCallback, useRef, useMemo } from 'react';
import { useUIStore } from '@/store/uiStore';
import { useMessageStore } from '@/store/messageStore';
import { useAuthStore } from '@/store/authStore';
import { tapFeedback } from '@/services/feedback';
import { aacSpeak } from '@/services/aacSpeak';
import { askAI } from '@/services/aiService';
import { useSettingsStore } from '@/store/settingsStore';
import { useT } from '@/engine/useT';
import { MATH_ITEMS } from '@/constants/mathSymbols';
import type { MathCategory } from '@/types';

const CATEGORIES: { key: MathCategory; i18n: string; icon: string }[] = [
  { key: 'basic',      i18n: 'math_basic',          icon: '+-' },
  { key: 'digits',     i18n: 'math_numbers',        icon: '#' },
  { key: 'algebra',    i18n: 'math_algebra',        icon: 'x²' },
  { key: 'constants',  i18n: 'math_constants',      icon: 'π' },
  { key: 'trig',       i18n: 'math_trigonometry',   icon: 'sin' },
  { key: 'calculus',   i18n: 'math_calculus',       icon: '∫' },
  { key: 'greek',      i18n: 'math_greek_letters',  icon: 'α' },
  { key: 'logic-sets', i18n: 'math_logic_sets',     icon: '∈' },
];

const TTS_MAP: Record<string, string> = Object.fromEntries(
  MATH_ITEMS.map((m) => [m.symbol, m.ttsText])
);

const MATH_TUTOR_CONTEXT = 'math-tutor';

function expressionToSpeech(expr: string): string {
  let speech = expr;
  const sorted = Object.entries(TTS_MAP).sort((a, b) => b[0].length - a[0].length);
  for (const [sym, word] of sorted) {
    speech = speech.replaceAll(sym, ` ${word} `);
  }
  return speech.replace(/\s+/g, ' ').trim();
}

export default function MathPanel() {
  const { sidePanel, closeSidePanel } = useUIStore();
  const { appendText } = useMessageStore();
  const { speechRate, speechVolume } = useSettingsStore();
  const profile = useAuthStore((s) => s.profile);
  const { t, outputTtsCode } = useT();
  const [expression, setExpression] = useState('');
  const [activeCategory, setActiveCategory] = useState<MathCategory>('basic');
  const [aiHint, setAiHint] = useState('');
  const [aiLoading, setAiLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const categoryItems = useMemo(
    () => MATH_ITEMS.filter((m) => m.category === activeCategory).sort((a, b) => a.sortOrder - b.sortOrder),
    [activeCategory]
  );

  if (sidePanel !== 'math') return null;

  const aiEnabled = !!profile;

  const addToExpression = (val: string) => {
    tapFeedback();
    const needsSpace = val.length > 1 || '+-×÷=≠≈<>≤≥±·'.includes(val);
    setExpression((prev) => {
      if (needsSpace) return prev + (prev && !prev.endsWith(' ') ? ' ' : '') + val + ' ';
      return prev + val;
    });
    setAiHint('');
  };

  const backspace = () => {
    tapFeedback();
    setAiHint('');
    setExpression((prev) => {
      if (prev.endsWith(' ')) {
        const trimmed = prev.trimEnd();
        const lastSpace = trimmed.lastIndexOf(' ');
        return lastSpace >= 0 ? prev.slice(0, lastSpace + 1) : '';
      }
      return prev.slice(0, -1);
    });
  };

  const clearAll = () => { tapFeedback(); setExpression(''); setAiHint(''); };

  const speakExpression = useCallback(() => {
    tapFeedback();
    if (!expression.trim()) return;
    aacSpeak(expressionToSpeech(expression), speechRate, speechVolume);
  }, [expression, speechRate, speechVolume, outputTtsCode]);

  const sendToMessage = () => {
    tapFeedback();
    if (!expression.trim()) return;
    appendText(expression.trim());
    setExpression('');
    setAiHint('');
  };

  const askMathTutor = async (mode: 'help' | 'solve' | 'check') => {
    if (!expression.trim() || !aiEnabled) return;
    tapFeedback();
    setAiLoading(true);
    setAiHint('');

    const prompts: Record<string, string> = {
      help: `The child wrote this math expression: "${expression}". They need help understanding what to do next. Give a gentle hint — don't solve it, just guide them to the next step. Use simple words. Be encouraging. Max 2 sentences.`,
      solve: `The child wrote: "${expression}". Show the solution step by step. Use simple language a child can understand. Use math symbols. Be encouraging — say "Great job trying!" or similar. Max 4 short steps.`,
      check: `The child wrote: "${expression}". Check if this is correct. If there's an error, explain what went wrong gently and show how to fix it. If it's correct, celebrate! Use simple words. Max 2 sentences.`,
    };

    let buffer = '';
    try {
      await askAI(prompts[mode], MATH_TUTOR_CONTEXT, (delta) => {
        buffer += delta;
        setAiHint(buffer);
      });
      setAiHint(buffer);
      if (buffer) aacSpeak(buffer, speechRate, speechVolume);
    } catch {
      setAiHint('Could not reach the math helper right now.');
    }
    setAiLoading(false);
    setTimeout(() => scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' }), 100);
  };

  const mathKey = 'aac-btn surface-key text-primary rounded-lg font-bold select-none border border-theme flex items-center justify-center';

  return (
    <section
      aria-label={t('math')}
      className="flex-[3] min-h-0 flex flex-col surface-bar border-y border-theme"
    >
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-2 border-b border-theme shrink-0">
        <span className="text-primary font-bold text-xl">{t('math')}</span>
        <div className="flex gap-2">
          <button onClick={sendToMessage} className="aac-btn bg-[#4CAF50] text-white rounded-lg px-4 py-2 font-bold text-base">
            ✓ {t('done')}
          </button>
          <button onClick={() => { tapFeedback(); closeSidePanel(); }} aria-label={t('close_panel')} className="aac-btn w-10 h-10 rounded-lg surface-key text-muted text-xl flex items-center justify-center border border-theme">✕</button>
        </div>
      </div>

      {/* Canvas — expression display + AI tutor */}
      <div ref={scrollRef} className="flex-1 min-h-0 overflow-y-auto px-4 py-3 space-y-3">
        {/* Expression canvas */}
        <div className="flex items-center justify-center bg-white dark:bg-[#1a1a2e] rounded-xl border-2 border-theme min-h-[clamp(80px,15svh,140px)] px-4 relative">
          <span className="text-[clamp(1.75rem,5vw,3.5rem)] font-mono text-primary tracking-wide text-center break-all py-3">
            {expression || <span className="text-dim text-[clamp(0.9rem,2.5vw,1.25rem)]">5 × 6 =</span>}
          </span>
          <div className="absolute bottom-1.5 right-3 flex gap-1.5">
            <button onClick={speakExpression} className="aac-btn w-8 h-8 rounded-full surface-key text-muted flex items-center justify-center border border-theme text-sm" aria-label={t('speak')}>🔊</button>
            <button onClick={clearAll} className="aac-btn w-8 h-8 rounded-full surface-key text-muted flex items-center justify-center border border-theme text-xs" aria-label={t('clear')}>C</button>
          </div>
        </div>

        {/* AI Tutor buttons */}
        {aiEnabled && expression.trim() && (
          <div className="flex gap-2">
            <button
              onClick={() => askMathTutor('help')}
              disabled={aiLoading}
              className="aac-btn flex-1 bg-[#2196F3] text-white rounded-lg py-2.5 font-bold text-base flex items-center justify-center gap-1.5"
            >
              💡 Hint
            </button>
            <button
              onClick={() => askMathTutor('check')}
              disabled={aiLoading}
              className="aac-btn flex-1 bg-[#FF9800] text-white rounded-lg py-2.5 font-bold text-base flex items-center justify-center gap-1.5"
            >
              ✓ Check
            </button>
            <button
              onClick={() => askMathTutor('solve')}
              disabled={aiLoading}
              className="aac-btn flex-1 bg-[#9C27B0] text-white rounded-lg py-2.5 font-bold text-base flex items-center justify-center gap-1.5"
            >
              🎓 Solve
            </button>
          </div>
        )}

        {/* AI response */}
        {(aiHint || aiLoading) && (
          <div className="bg-[#E3F2FD] dark:bg-[#1a2a4a] rounded-xl p-4 border border-[#90CAF9] dark:border-[#2a4a7a]">
            <div className="flex items-start gap-2">
              <span className="text-2xl shrink-0">🤖</span>
              <div className="text-primary text-base leading-relaxed">
                {aiLoading && !aiHint ? (
                  <span className="text-muted animate-pulse">{t('thinking')}</span>
                ) : (
                  aiHint.split('\n').map((line, i) => (
                    <p key={i} className={i > 0 ? 'mt-2' : ''}>{line}</p>
                  ))
                )}
              </div>
            </div>
            {aiHint && (
              <button
                onClick={() => { tapFeedback(); aacSpeak(aiHint, speechRate, speechVolume); }}
                className="aac-btn mt-2 text-[#2196F3] text-sm font-bold"
              >
                🔊 Read aloud
              </button>
            )}
          </div>
        )}
      </div>

      {/* Math keyboard */}
      <div className="shrink-0 border-t border-theme p-2 space-y-1.5">
        {/* Category tabs */}
        <div className="flex gap-1 overflow-x-auto no-scrollbar">
          {CATEGORIES.map((cat) => (
            <button
              key={cat.key}
              onClick={() => { tapFeedback(); setActiveCategory(cat.key); }}
              className={`${mathKey} px-2.5 py-1.5 text-xs whitespace-nowrap shrink-0 ${
                activeCategory === cat.key ? 'bg-[#4CAF50] text-white border-transparent' : ''
              }`}
            >
              <span className="font-mono mr-1">{cat.icon}</span>
              <span className="hidden sm:inline">{t(cat.i18n)}</span>
            </button>
          ))}
        </div>

        {/* Symbol grid for active category */}
        <div className="flex gap-1.5 flex-wrap max-h-[clamp(44px,10svh,88px)] overflow-y-auto">
          {categoryItems.map((item) => (
            <button
              key={item.id}
              onClick={() => addToExpression(item.symbol)}
              className={`${mathKey} min-w-[clamp(36px,8vw,48px)] py-2 text-lg`}
              title={item.label}
              aria-label={item.ttsText}
            >
              {item.symbol}
            </button>
          ))}
        </div>

        {/* Number pad — always visible */}
        <div className="flex gap-1.5">
          {['1', '2', '3', '4', '5', '6', '7', '8', '9', '0'].map((d) => (
            <button key={d} onClick={() => addToExpression(d)} className={`${mathKey} flex-1 py-2.5 text-xl`}>
              {d}
            </button>
          ))}
        </div>

        {/* Variables + space + speak/send + backspace */}
        <div className="flex gap-1.5">
          {['x', 'y', 'z', 'a', 'b', 'n'].map((v) => (
            <button key={v} onClick={() => addToExpression(v)} className={`${mathKey} flex-1 py-2 text-lg italic`}>
              {v}
            </button>
          ))}
          <button onClick={() => addToExpression(' ')} className={`${mathKey} flex-[2] py-2 text-sm`}>
            ␣
          </button>
          <button onClick={backspace} className={`${mathKey} px-3 py-2 text-lg`} aria-label={t('backspace')}>⌫</button>
          <button onClick={sendToMessage} className="aac-btn bg-[#4CAF50] text-white rounded-lg flex-[2] py-2 font-bold text-base flex items-center justify-center">
            {t('speak')} ▶
          </button>
        </div>
      </div>
    </section>
  );
}

