  const settings = useSettingsStore();
  const { t } = useT();
  const { customCategories, customPhrases, addCustomCategory, removeCustomCategory, addCustomPhrase, removeCustomPhrase, allCategories, hiddenCategoryIds, hideCategoryId, unhideCategoryId, hiddenPhraseIds, hideDefaultPhrase, unhideDefaultPhrase } = useCategoryStore();
  const [newCatName, setNewCatName] = useState('');
  const [newCatIcon, setNewCatIcon] = useState('📌');
  const [newPhraseText, setNewPhraseText] = useState('');
  const [newPhraseCat, setNewPhraseCat] = useState('');
  const [wordVisCat, setWordVisCat] = useState('');
  const profile = useAuthStore((s) => s.profile);
  const profileLoaded = useAuthStore((s) => s.loaded);
  const profileLoading = useAuthStore((s) => s.loading);
  const refreshProfile = useAuthStore((s) => s.refresh);

  useEffect(() => {
    if (showSettings) refreshProfile();
  }, [showSettings, refreshProfile]);

  if (!showSettings) return null;

  const cats = allCategories(true);
  const hiddenSet = new Set(hiddenCategoryIds);
  const GRID_OPTIONS: GridSize[] = [4, 6, 9, 12, 16, 20];

  const sectionTitle = 'text-muted font-semibold text-base uppercase tracking-wider mb-3';

  return (
    <div role="dialog" aria-modal="true" className="modal-backdrop fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4" onClick={toggleSettings}>
      <div className="surface-bar rounded-2xl w-full max-w-lg max-h-[85svh] flex flex-col border border-theme shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between px-5 py-3 border-b border-theme">
          <h2 className="text-primary font-bold text-lg">{t('settings')}</h2>
          <button onClick={toggleSettings} aria-label={t('close_settings')} className="text-muted hover:text-primary text-xl">✕</button>
        </div>
        <div className="flex-1 overflow-y-auto p-5 space-y-6">
          {/* Theme */}
          <div>
            <h3 className={sectionTitle}>{t('theme')}</h3>
            <div className="grid grid-cols-2 gap-2">
              <button
                onClick={() => settings.setTheme('light')}
                aria-pressed={settings.theme === 'light'}
                className={`aac-btn rounded-xl px-4 py-4 text-lg font-semibold border border-theme ${
                  settings.theme === 'light' ? 'bg-[#4CAF50] text-white border-transparent' : 'surface-key text-primary'
                }`}
              >
                ☀ {t('light')}
              </button>
              <button
                onClick={() => settings.setTheme('dark')}
                aria-pressed={settings.theme === 'dark'}
                className={`aac-btn rounded-xl px-4 py-4 text-lg font-semibold border border-theme ${
                  settings.theme === 'dark' ? 'bg-[#4CAF50] text-white border-transparent' : 'surface-key text-primary'
                }`}
              >
                🌙 {t('dark')}
              </button>
            </div>
          </div>

          {/* Language */}
          <div>
            <h3 className={sectionTitle}>{t('language')}</h3>
            <div className="grid grid-cols-3 gap-2">
              {LANG_META.map((lang) => (
                <button
                  key={lang.code}
                  onClick={() => settings.update({ language: lang.code as SupportedLanguage })}
                  className={`aac-btn rounded-xl px-3 py-3 text-base text-left border border-theme ${
                    settings.language === lang.code ? 'bg-[#4CAF50] text-white border-transparent' : 'surface-key text-primary'
                  }`}
                >
                  <div className="font-semibold">{lang.nativeName}</div>
                  <div className="text-sm opacity-70">{lang.name}</div>
                </button>
              ))}
            </div>
          </div>

          {/* Input Modes — all accessibility input methods */}
          <div>
            <h3 className={sectionTitle}>Input Modes</h3>
            <InputModesSettings />
          </div>

          {/* Toolbar Customization — reorder/hide buttons + manage apps */}
          <div>
            <h3 className={sectionTitle}>Toolbar Buttons</h3>
            <ToolbarCustomization />
          </div>

          {/* Hand Calibration */}
          {settings.showHandCalibration && (
            <div>
              <h3 className={sectionTitle}>Hand Calibration</h3>
              <HandProfileSection />
            </div>
          )}

          {/* Accessibility */}
          <div>
            <h3 className={sectionTitle}>{t('accessibility')}</h3>
            <label className="flex items-center justify-between py-2">
              <span className="text-primary text-lg">{t('high_contrast')}</span>
              <button
                onClick={() => settings.update({ highContrast: !settings.highContrast })}
                aria-pressed={settings.highContrast}
                aria-label={t('high_contrast')}
                className={`w-14 h-8 rounded-full transition-colors ${settings.highContrast ? 'bg-[#FFD700]' : 'bg-[#999]'}`}
              >
                <div className={`w-6 h-6 rounded-full bg-white transition-transform mx-1 ${settings.highContrast ? 'translate-x-6' : ''}`} />
              </button>
            </label>
          </div>

          {/* Head Tracking */}
          <HeadTrackingSettings />

          {/* Vocabulary Set */}
          <div>
            <h3 className={sectionTitle}>{t('vocab_set')}</h3>
            <div className="grid grid-cols-2 gap-2">
              {VOCAB_SETS.map((vs) => (
                <button
                  key={vs.id}
                  onClick={() => { tapFeedback(); settings.update({ activeVocabSet: vs.id }); }}
                  aria-pressed={settings.activeVocabSet === vs.id}
                  className={`aac-btn rounded-xl px-3 py-3 text-left border border-theme ${
                    settings.activeVocabSet === vs.id ? 'bg-[#4CAF50] text-white border-transparent' : 'surface-key text-primary'
                  }`}
                >
                  <div className="flex items-center gap-2">
                    <span className="text-xl">{vs.icon}</span>
                    <span className="font-semibold text-sm">{t(vs.nameKey)}</span>
                    {vs.tier !== 'free' && (
                      <span className="ml-auto text-[10px] uppercase tracking-wider px-1.5 py-0.5 rounded bg-black/15 font-bold">{vs.tier}</span>
                    )}
                  </div>
                  <p className={`text-xs mt-1 ${settings.activeVocabSet === vs.id ? 'opacity-80' : 'text-muted'}`}>{t(vs.descKey)}</p>
                </button>
              ))}
            </div>
          </div>

          {/* Category Visibility */}
          <div>
            <h3 className={sectionTitle}>{t('category_visibility')}</h3>
            <p className="text-muted text-sm mb-3">{t('slp_tip_categories')}</p>
            <div className="max-h-[240px] overflow-y-auto space-y-1 border border-theme rounded-xl p-2">
              {cats.map((cat) => {
                const visible = !hiddenSet.has(cat.id);
                return (
                  <label key={cat.id} className="flex items-center justify-between py-2 px-2 rounded-lg hover:bg-black/5">
                    <span className="text-primary text-base">{cat.icon} {cat.name}</span>
                    <button
                      onClick={() => { tapFeedback(); visible ? hideCategoryId(cat.id) : unhideCategoryId(cat.id); }}
                      aria-pressed={visible}
                      aria-label={`${cat.name} visibility`}
                      className={`w-14 h-8 rounded-full transition-colors ${visible ? 'bg-[#4CAF50]' : 'bg-[#999]'}`}
                    >
                      <div className={`w-6 h-6 rounded-full bg-white transition-transform mx-1 ${visible ? 'translate-x-6' : ''}`} />
                    </button>
                  </label>
                );
              })}
            </div>
          </div>

          {/* Word Visibility */}
          <div>
            <h3 className={sectionTitle}>{t('word_visibility')}</h3>
            <select
              value={wordVisCat}
              onChange={(e) => { tapFeedback(); setWordVisCat(e.target.value); }}
              className="w-full surface-key rounded-lg px-3 py-2 text-sm border border-theme mb-3"
            >
              <option value="">{t('select_category')}</option>
              {cats.map((c) => <option key={c.id} value={c.id}>{c.icon} {c.nameKey ? t(c.nameKey) : c.name}</option>)}
            </select>
            {wordVisCat && (
              <div className="max-h-[240px] overflow-y-auto space-y-1 border border-theme rounded-xl p-2">
                {DEFAULT_PHRASES.filter((p) => p.categoryId === wordVisCat).map((p) => {
                  const phraseVisible = !hiddenPhraseIds.includes(p.id);
                  const localText = getPhraseText(p.id, settings.language, p.text);
                  return (
                    <label key={p.id} className="flex items-center justify-between py-2 px-2 rounded-lg hover:bg-black/5">
                      <span className="text-primary text-base">{localText}</span>
                      <button
                        onClick={() => { tapFeedback(); phraseVisible ? hideDefaultPhrase(p.id) : unhideDefaultPhrase(p.id); }}
                        aria-pressed={phraseVisible}
                        aria-label={phraseVisible ? t('hide_word') : t('show_word')}
                        className={`w-14 h-8 rounded-full transition-colors ${phraseVisible ? 'bg-[#4CAF50]' : 'bg-[#999]'}`}
                      >
                        <div className={`w-6 h-6 rounded-full bg-white transition-transform mx-1 ${phraseVisible ? 'translate-x-6' : ''}`} />
                      </button>
                    </label>
                  );
                })}
              </div>
            )}
          </div>

          {/* Grid Size */}
          <div>
            <h3 className={sectionTitle}>{t('grid_size')}</h3>
            <p className="text-muted text-sm mb-3">{t('slp_tip_grid')}</p>
            <div className="grid grid-cols-6 gap-2">
              {GRID_OPTIONS.map((size) => (
                <button
                  key={size}
                  onClick={() => settings.update({ gridSize: size })}
                  className={`aac-btn rounded-xl px-2 py-3 text-lg font-bold border border-theme text-center ${
                    settings.gridSize === size ? 'bg-[#4CAF50] text-white border-transparent' : 'surface-key text-primary'
                  }`}
                >
                  {size}
                </button>
              ))}
            </div>
          </div>

          {/* Speech */}
          <div>
            <h3 className={sectionTitle}>{t('voice')}</h3>
            <label className="flex items-center justify-between mb-2">
              <span className="text-primary text-lg">{t('speed')}</span>
              <span className="text-muted text-lg">{settings.speechRate.toFixed(1)}</span>
            </label>
            <input
              type="range" min="0.1" max="1" step="0.1" value={settings.speechRate}
              onChange={(e) => settings.update({ speechRate: parseFloat(e.target.value) })}
              className="w-full accent-[#4CAF50]"
            />
            <label className="flex items-center justify-between mb-2 mt-4">
              <span className="text-primary text-lg">{t('volume')}</span>
              <span className="text-muted text-lg">{Math.round(settings.speechVolume * 100)}%</span>
            </label>
            <input
              type="range" min="0" max="1" step="0.1" value={settings.speechVolume}
              onChange={(e) => settings.update({ speechVolume: parseFloat(e.target.value) })}
              className="w-full accent-[#2196F3]"
            />
          </div>

          {/* Custom Categories */}
          <div>
            <h3 className={sectionTitle}>{t('custom_categories')}</h3>
            <div className="flex gap-2 mb-2">
              <input value={newCatIcon} onChange={(e) => setNewCatIcon(e.target.value)} className="w-12 surface-key rounded-lg text-center text-xl p-2 border border-theme" maxLength={2} />
              <input value={newCatName} onChange={(e) => setNewCatName(e.target.value)} placeholder={t('category_name')} className="flex-1 surface-key rounded-lg px-3 py-2 border border-theme" />
              <button
                onClick={() => { if (newCatName.trim()) { addCustomCategory(newCatName.trim(), newCatIcon || '📌'); setNewCatName(''); } }}
                className="aac-btn bg-[#4CAF50] text-white px-5 py-3 rounded-lg font-semibold text-base hover:bg-[#388E3C]"
              >
                {t('add')}
              </button>
            </div>
            {customCategories.map((c) => (
              <div key={c.id} className="flex items-center justify-between surface-key rounded-lg px-3 py-2 mb-1 border border-theme">
                <span className="text-primary">{c.icon} {c.name}</span>
                <button onClick={() => removeCustomCategory(c.id)} className="text-[#F44336] text-sm hover:underline">{t('remove')}</button>
              </div>
            ))}
          </div>

          {/* Custom Phrases */}
          <div>
            <h3 className={sectionTitle}>{t('custom_phrases')}</h3>
            <div className="flex gap-2 mb-2">
              <select value={newPhraseCat} onChange={(e) => setNewPhraseCat(e.target.value)} className="surface-key rounded-lg px-2 py-2 text-sm border border-theme">
                <option value="">{t('category_select')}</option>
                {cats.map((c) => <option key={c.id} value={c.id}>{c.icon} {c.name}</option>)}
              </select>
              <input value={newPhraseText} onChange={(e) => setNewPhraseText(e.target.value)} placeholder={t('phrase_text')} className="flex-1 surface-key rounded-lg px-3 py-2 border border-theme" />
              <button
                onClick={() => { if (newPhraseText.trim() && newPhraseCat) { addCustomPhrase(newPhraseCat, newPhraseText.trim()); setNewPhraseText(''); setNewPhraseCat(''); } }}
                className="aac-btn bg-[#4CAF50] text-white px-5 py-3 rounded-lg font-semibold text-base hover:bg-[#388E3C]"
              >
                {t('add')}
              </button>
            </div>
            {customPhrases.map((p) => {
              const cat = cats.find((c) => c.id === p.categoryId);
              return (
                <div key={p.id} className="flex items-center justify-between surface-key rounded-lg px-3 py-2 mb-1 border border-theme">
                  <span className="text-primary"><span className="text-muted text-xs">{cat?.icon}</span> {p.text}</span>
                  <button onClick={() => removeCustomPhrase(p.id)} className="text-[#F44336] text-sm hover:underline">{t('remove')}</button>
                </div>
              );
            })}
          </div>

          {/* Export / Import — Copy/Paste to/from other apps */}
          <div>
            <h3 className={sectionTitle}>{t('export_import')}</h3>
            <p className="text-muted text-sm mb-3">{t('export_import_desc')}</p>
            <div className="grid grid-cols-2 gap-2">
              <button
                onClick={() => {
                  tapFeedback();
                  const data = {
                    version: 1,
                    categories: useCategoryStore.getState().customCategories,
                    phrases: useCategoryStore.getState().customPhrases.filter(p => !p.deletedAt),
                    hiddenCategories: useCategoryStore.getState().hiddenCategoryIds,
                    hiddenPhrases: useCategoryStore.getState().hiddenPhraseIds,
                    settings: { gridSize: settings.gridSize, activeVocabSet: settings.activeVocabSet },
                  };
                  navigator.clipboard.writeText(JSON.stringify(data, null, 2));
                }}
                className="aac-btn rounded-xl px-4 py-4 text-lg font-semibold border border-theme surface-key text-primary"
              >
                📋 {t('export_clipboard')}
              </button>
              <button
                onClick={async () => {
                  tapFeedback();
                  try {
                    const text = await navigator.clipboard.readText();
                    const data = JSON.parse(text);
                    if (data.version && data.categories) {
                      const store = useCategoryStore.getState();
                      for (const cat of data.categories || []) store.addCustomCategory(cat.name, cat.icon);
                      for (const phrase of data.phrases || []) store.addCustomPhrase(phrase.categoryId, phrase.text);
                    }
                  } catch { /* invalid clipboard data */ }
                }}
                className="aac-btn rounded-xl px-4 py-4 text-lg font-semibold border border-theme surface-key text-primary"
              >
                📥 {t('import_clipboard')}
              </button>
            </div>
          </div>

          {/* Synalux Account */}
          <div>
            <h3 className={sectionTitle}>{t('synalux_account')}</h3>
            {!profileLoaded || profileLoading ? (
              <p className="text-muted text-sm">{t('checking_sign_in')}</p>
            ) : profile ? (
              <div className="space-y-2">
                <div className="surface-key rounded-lg px-3 py-3 border border-theme">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-muted text-xs uppercase tracking-wider">{t('signed_in_as')}</span>
                    <span className="text-[#4CAF50] text-xs">● {t('active')}</span>
                  </div>
                  <p className="text-primary font-semibold text-sm break-all">{profile.email || profile.name}</p>
                </div>
                <div className="surface-key rounded-lg px-3 py-3 border border-theme">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-muted text-xs uppercase tracking-wider">{t('subscription')}</span>
                    {profile.isPlatformAdmin && <span className="text-[#FFD700] text-xs">★ {t('admin')}</span>}
                  </div>
                  <p className="text-primary font-semibold text-sm">{t(PLAN_LABEL_KEYS[profile.plan]) || profile.plan}</p>
                </div>
                <a href={synaluxSignOutUrl()} className="block text-center text-[#F44336] text-sm hover:underline pt-1">
                  {t('sign_out')}
                </a>
              </div>
            ) : (
              <div>
                <p className="text-muted text-sm mb-3">{t('sign_in_synalux_desc')}</p>
                <a
                  href={synaluxSignInUrl()}
                  data-testid="synalux-signin"
                  className="aac-btn block w-full text-center bg-[#4CAF50] text-white px-4 py-4 rounded-lg font-semibold hover:bg-[#388E3C] text-lg"
                >
                  {t('sign_in_with_synalux')}
                </a>
                <p className="text-dim text-xs mt-2">{t('core_aac_no_account')}</p>
              </div>
            )}
          </div>

          {/* Resources */}
          <div>
            <h3 className={sectionTitle}>{t('aac_resources')}</h3>
            <a href="https://www.asha.org/practice-portal/professional-issues/augmentative-and-alternative-communication/" target="_blank" rel="noopener" className="block text-[#2563eb] text-sm hover:underline mb-1">ASHA — AAC Practice Portal</a>
            <a href="https://aac-rerc.psu.edu/" target="_blank" rel="noopener" className="block text-[#2563eb] text-sm hover:underline mb-1">AAC-RERC — Research Center</a>
            <a href="https://praacticalaac.org/" target="_blank" rel="noopener" className="block text-[#2563eb] text-sm hover:underline mb-1">PrAACtical AAC — Implementation Resources</a>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';
import { useEffect, useRef, useState } from 'react';
import { useUIStore } from '@/store/uiStore';
import { useMessageStore } from '@/store/messageStore';
import { useSettingsStore, type ToolbarButtonId, DEFAULT_TOOLBAR_ORDER } from '@/store/settingsStore';
import { SupportedLanguage, LANG_META } from '@/engine/i18n';
import { useSyncStatus } from './SyncProvider';
import { tapFeedback } from '@/services/feedback';
import { useT } from '@/engine/useT';
import { isVoiceInputSupported, startVoiceInput, VoiceSession } from '@/services/voiceInputService';
import { correctText } from '@/services/textCorrectService';

const SYNC_ICONS: Record<string, string> = {
  idle: '⬡', syncing: '🔄', synced: '🟢', offline: '🔸', error: '🔴',
};

// Built-in button registry. To add a new button:
//   1. add the id to ToolbarButtonId in settingsStore.ts
//   2. add it to DEFAULT_TOOLBAR_ORDER (or skip if it should be opt-in)
//   3. register the icon + handler factory here
// The factory receives the action callbacks + current state and returns the
// per-render button props. No new field on the registry should ship without
// also wiring it into a real consumer (per pre-commit-protocol Rule 2).
interface ButtonHandlers {
  openCategories: () => void;
  openMath: () => void;
  openAIChat: () => void;
  openCaregiver: () => void;
  openSchedule: () => void;
  openGames: () => void;
  openMarketplace: () => void;
  toggleHistory: () => void;
  toggleSettings: () => void;
  triggerAlert: () => void;
  toggleSound: () => void;
  toggleMic: () => void;
  soundEnabled: boolean;
  listening: boolean;
  voiceSupported: boolean;
}

interface RenderedButton {
  id: string;
  icon: string;
  ariaLabel: string;
  title: string;
  onClick: () => void;
  highlighted?: boolean;
  pulsing?: boolean;
}

function buildBuiltInButtons(t: (k: string) => string, h: ButtonHandlers): Record<ToolbarButtonId, RenderedButton | null> {
  return {
    categories: { id: 'categories', icon: '📂', ariaLabel: t('categories'), title: t('categories'), onClick: h.openCategories },
    mic: h.voiceSupported ? {
      id: 'mic',
      icon: h.listening ? '⏺' : '🎙',
      ariaLabel: h.listening ? t('stop_voice') : t('start_voice'),
      title: h.listening ? t('stop_voice') : t('start_voice'),
      onClick: h.toggleMic,
      highlighted: h.listening,
      pulsing: h.listening,
    } : null,
    schedule: { id: 'schedule', icon: '📅', ariaLabel: t('schedule'), title: t('schedule'), onClick: h.openSchedule },
    marketplace: { id: 'marketplace', icon: '🏪', ariaLabel: t('marketplace'), title: t('marketplace'), onClick: h.openMarketplace },
    alert: { id: 'alert', icon: '🚨', ariaLabel: t('alert'), title: t('alert'), onClick: h.triggerAlert },
    math: { id: 'math', icon: '🔢', ariaLabel: t('math'), title: t('math'), onClick: h.openMath },
    ai_chat: { id: 'ai_chat', icon: '✨', ariaLabel: t('ai_chat'), title: t('ai_chat'), onClick: h.openAIChat },
    notes: { id: 'notes', icon: '📋', ariaLabel: t('notes'), title: t('notes'), onClick: h.openCaregiver },
    games: { id: 'games', icon: '🎮', ariaLabel: t('games'), title: t('games'), onClick: h.openGames },
    history: { id: 'history', icon: '📜', ariaLabel: t('history'), title: t('history'), onClick: h.toggleHistory },
    sound: {
      id: 'sound',
      icon: h.soundEnabled ? '🔊' : '🔇',
      ariaLabel: h.soundEnabled ? t('sound_on') : t('sound_off'),
      title: h.soundEnabled ? t('sound_on') : t('sound_off'),
      onClick: h.toggleSound,
      highlighted: h.soundEnabled,
    },
    settings: { id: 'settings', icon: '⚙️', ariaLabel: t('settings'), title: t('settings'), onClick: h.toggleSettings },
  };
}

// Marketplace app ID → (icon, label-key). Apps not in this map fall back to
// a generic puzzle-piece icon so they're still clickable. Keep in sync with
// MarketplacePanel CATALOG.
const APP_ICON_MAP: Record<string, { icon: string; labelKey?: string; label?: string }> = {
  'symbol-libraries': { icon: '📚', labelKey: 'mp_symbol_libraries' },
  'board-templates': { icon: '📋', labelKey: 'mp_board_templates' },
  'vocab-my-core': { icon: '⚡', labelKey: 'vs_my_core' },
  'vocab-wordpower': { icon: '💪', labelKey: 'vs_wordpower' },
  'vocab-gateway': { icon: '🚪', labelKey: 'vs_gateway' },
  'vocab-aphasia': { icon: '🧠', labelKey: 'vs_aphasia' },
  'vocab-social-chat': { icon: '💬', labelKey: 'vs_social_chat' },
  'game-packs': { icon: '🎮', labelKey: 'mp_game_packs' },
  'voice-packs': { icon: '🎙', labelKey: 'mp_voice_packs' },
  'picture-editor': { icon: '🖼', labelKey: 'mp_picture_editor' },
  'music-composer': { icon: '🎵', labelKey: 'mp_music_composer' },
  'aac-designer': { icon: '🎨', labelKey: 'mp_aac_designer' },
  'video-composer': { icon: '🎬', labelKey: 'mp_video_composer' },
};

function appButton(appId: string, t: (k: string) => string, openMarketplace: () => void): RenderedButton {
  const meta = APP_ICON_MAP[appId];
  // Installed apps that aren't in the map fall back gracefully so the
  // toolbar still renders something clickable; tapping any app button
  // opens the marketplace panel where the user can configure / launch.
  // (A future iteration should route to the app-specific panel; for now
  // the marketplace panel is the universal landing place.)
  const labelText = meta?.labelKey ? t(meta.labelKey) : (meta?.label ?? appId);
  return {
    id: `app:${appId}`,
    icon: meta?.icon ?? '🧩',
    ariaLabel: labelText,
    title: labelText,
    onClick: openMarketplace,
  };
}

export default function Toolbar() {
  const { openCategories, openMath, openCaregiver, openAIChat, openSchedule, openGames, openMarketplace, toggleHistory, toggleSettings, triggerAlert } = useUIStore();
  const { soundEnabled, toggleSound, appendText } = useMessageStore();
  const language = useSettingsStore((s) => s.language);
  const outputLanguage = useSettingsStore((s) => s.outputLanguage);
  const updateSettings = useSettingsStore((s) => s.update);
  const toolbarConfig = useSettingsStore((s) => s.toolbarConfig);
  const installedApps = useSettingsStore((s) => s.installedApps);
  const syncStatus = useSyncStatus();
  const { t, ttsCode } = useT();
  const [listening, setListening] = useState(false);
  const [showLangPicker, setShowLangPicker] = useState<'input' | 'output' | null>(null);
  const voiceRef = useRef<VoiceSession | null>(null);
  const langRef = useRef<HTMLDivElement>(null);
  const voiceSupported = isVoiceInputSupported();

  useEffect(() => () => { voiceRef.current?.stop(); voiceRef.current = null; setListening(false); }, [language]);
  useEffect(() => {
    if (!showLangPicker) return;
    const handler = (e: MouseEvent) => {
      if (langRef.current && !langRef.current.contains(e.target as Node)) setShowLangPicker(null);
    };
    document.addEventListener('pointerdown', handler);
    return () => document.removeEventListener('pointerdown', handler);
  }, [showLangPicker]);

  const toggleMic = () => {
    tapFeedback();
    if (voiceRef.current) { voiceRef.current.stop(); voiceRef.current = null; setListening(false); return; }
    const session = startVoiceInput({
      lang: ttsCode,
      onInterim: () => {},
      onFinal: async (txt) => { const fixed = await correctText(txt.trim(), language); appendText((fixed || txt).trim() + ' '); },
      onError: () => { voiceRef.current = null; setListening(false); },
    });
    if (session) { voiceRef.current = session; setListening(true); }
  };

  const handlers: ButtonHandlers = {
    openCategories, openMath, openAIChat, openCaregiver, openSchedule, openGames, openMarketplace,
    toggleHistory, toggleSettings, triggerAlert,
    toggleSound: () => { tapFeedback(); toggleSound(); },
    toggleMic,
    soundEnabled, listening, voiceSupported,
  };

  const builtIns = buildBuiltInButtons(t, handlers);

  // Resolve the visible button list from config:
  //   - iterate toolbarConfig.order for built-in ids that are enabled
  //   - then append installed marketplace apps (in install order)
  // Disabled ids (enabled[id]===false) stay in `order` but skip rendering;
  // they reappear in original position when re-enabled.
  // Forward-compat: any id in DEFAULT_TOOLBAR_ORDER that's missing from a
  // persisted user config gets appended at the end so new built-ins show
  // up after upgrade without a migration.
  const visibleIds: string[] = [];
  const seen = new Set<ToolbarButtonId>();
  for (const id of toolbarConfig.order) {
    if (id === 'settings' || toolbarConfig.enabled[id] !== false) visibleIds.push(id);
    seen.add(id);
  }
  for (const id of DEFAULT_TOOLBAR_ORDER) {
    if (!seen.has(id) && (id === 'settings' || toolbarConfig.enabled[id] !== false)) visibleIds.push(id);
  }
  const appIds = installedApps.map((a) => `app:${a}`);
  const allButtons = [...visibleIds, ...appIds];

  const btnClass = 'aac-btn w-[clamp(2.25rem,7vw,3.25rem)] h-[clamp(2.25rem,7svh,3.25rem)] rounded-full text-[clamp(1rem,3.5vw,1.5rem)] select-none border border-theme shrink-0 flex items-center justify-center';
  const tap = (fn: () => void) => () => { tapFeedback(); fn(); };

  function renderButton(id: string): React.ReactNode {
    if (id.startsWith('app:')) {
      const b = appButton(id.slice(4), t, openMarketplace);
      return (
        <button
          key={id}
          className={`${btnClass} surface-key text-primary`}
          onClick={tap(b.onClick)}
          aria-label={b.ariaLabel}
          title={b.title}
        >{b.icon}</button>
      );
    }
    const b = builtIns[id as ToolbarButtonId];
    if (!b) return null; // mic when voice unsupported, etc.
    const colorClasses = b.highlighted
      ? (b.id === 'sound' ? 'bg-[#4CAF50] text-white border-transparent' : (b.id === 'mic' ? 'bg-[#F44336] text-white border-transparent' : 'surface-key text-primary'))
      : 'surface-key text-primary';
    const pulseClass = b.pulsing ? 'animate-pulse' : '';
    return (
      <button
        key={id}
        className={`${btnClass} ${colorClasses} ${pulseClass}`}
        onClick={tap(b.onClick)}
        aria-label={b.ariaLabel}
        title={b.title}
        aria-pressed={b.highlighted}
      >{b.icon}</button>
    );
  }

  return (
    <div className="flex items-center justify-between px-1 py-[clamp(0.1rem,0.3svh,0.25rem)] surface-bar shrink-0 border-b border-theme relative">
      {/* All buttons render in a single flat strip — no overflow menu. The
          flex-wrap allows the toolbar to break onto a second row when there
          are too many buttons (e.g. many marketplace apps installed). */}
      <div className="flex flex-wrap gap-1 items-center min-w-0">
        {allButtons.map((id) => renderButton(id))}
      </div>

      {/* Language pair selector (kept centered/right of the button strip).
          This stays hard-coded — it's not a toolbar button, it's the AAC
          translate-pair selector. */}
      <div ref={langRef} className="flex items-center gap-0.5 relative shrink-0 ml-2">
        <button
          className="aac-btn h-[clamp(1.75rem,5svh,2.5rem)] px-[clamp(0.3rem,1vw,0.5rem)] rounded-lg bg-[#2196F3] text-white font-bold text-[clamp(0.6rem,2vw,0.85rem)] uppercase select-none border-none"
          onClick={() => { tapFeedback(); setShowLangPicker(showLangPicker === 'input' ? null : 'input'); }}
        >
          {language}
        </button>
        <span className="text-[clamp(0.5rem,1.5vw,0.7rem)] text-muted">→</span>
        <button
          className={`aac-btn h-[clamp(1.75rem,5svh,2.5rem)] px-[clamp(0.3rem,1vw,0.5rem)] rounded-lg font-bold text-[clamp(0.6rem,2vw,0.85rem)] uppercase select-none border-none ${
            outputLanguage !== language ? 'bg-[#FF9800] text-white' : 'bg-[#4CAF50] text-white'
          }`}
          onClick={() => { tapFeedback(); setShowLangPicker(showLangPicker === 'output' ? null : 'output'); }}
        >
          {outputLanguage}
        </button>

        {showLangPicker && (
          <div
            className="absolute top-full mt-1 right-0 surface-bar rounded-xl border border-theme shadow-2xl z-50 p-2 grid grid-cols-3 sm:grid-cols-4 gap-1.5 max-h-[80svh] overflow-y-auto"
            style={{ width: 'min(94vw, 380px)' }}
          >
            {LANG_META.map((l) => (
              <button
                key={l.code}
                className={`aac-btn rounded-lg px-1 py-2 text-center font-bold border border-theme min-h-[clamp(2.75rem,7svh,3.5rem)] flex flex-col items-center justify-center gap-0.5 ${
                  (showLangPicker === 'input' ? language : outputLanguage) === l.code
                    ? 'bg-[#4CAF50] text-white border-transparent'
                    : 'surface-key text-primary'
                }`}
                onClick={() => {
                  tapFeedback();
                  if (showLangPicker === 'input') {
                    const prev = useSettingsStore.getState();
                    const sync = prev.language === prev.outputLanguage;
                    updateSettings({ language: l.code as SupportedLanguage, ...(sync ? { outputLanguage: l.code as SupportedLanguage } : {}) });
                  } else {
                    updateSettings({ outputLanguage: l.code as SupportedLanguage });
                  }
                  setShowLangPicker(null);
                }}
              >
                <div className="text-[clamp(0.75rem,3vw,0.95rem)] font-bold leading-tight whitespace-nowrap">{l.nativeName}</div>
                <div className="text-[clamp(0.55rem,1.8vw,0.7rem)] uppercase opacity-75">{l.code}</div>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Sync status indicator — informational only, not a toolbar button. */}
      <span className="text-[8px] text-dim ml-1 shrink-0" title={`Sync: ${syncStatus}`}>{SYNC_ICONS[syncStatus] ?? '⬡'}</span>
    </div>
  );
}

'use client';
import { useState, useEffect, useRef, useCallback } from 'react';
import { useSettingsStore } from '@/store/settingsStore';
import {
  startPoseTracker,
  isPoseTrackingSupported,
  savePoseCalibration,
  type PoseTrackerHandle,
  type TrackingTarget,
  type PoseCalibrationData,
} from '@/services/bodyPoseService';
import { aacSpeak } from '@/services/aacSpeak';
import { tapFeedback } from '@/services/feedback';

type Phase =
  | 'intro'
  | 'detecting'        // auto-detect which body parts are visible
  | 'calibrate-center' // hold still at center
  | 'calibrate-corners'// point to each corner
  | 'accuracy-test'    // tap random targets
  | 'complete';

interface DetectedPart {
  target: TrackingTarget;
  label: string;
  emoji: string;
  confidence: number;
}

const BODY_PARTS: Array<{ target: TrackingTarget; label: string; emoji: string }> = [
  { target: 'nose', label: 'Head', emoji: '🙂' },
  { target: 'right_wrist', label: 'Right Hand', emoji: '🤚' },
  { target: 'left_wrist', label: 'Left Hand', emoji: '🖐' },
  { target: 'right_index', label: 'Right Finger', emoji: '👆' },
  { target: 'left_index', label: 'Left Finger', emoji: '☝️' },
  { target: 'right_elbow', label: 'Right Elbow', emoji: '💪' },
  { target: 'left_elbow', label: 'Left Elbow', emoji: '💪' },
];

const CORNER_TARGETS = [
  { label: 'Top Left', x: 15, y: 15, emoji: '↖' },
  { label: 'Top Right', x: 85, y: 15, emoji: '↗' },
  { label: 'Bottom Right', x: 85, y: 85, emoji: '↘' },
  { label: 'Bottom Left', x: 15, y: 85, emoji: '↙' },
];

interface Props {
  onComplete: () => void;
  onCancel: () => void;
}

export default function TrackingSetupWizard({ onComplete, onCancel }: Props) {
  const { speechRate, speechVolume } = useSettingsStore();
  const [phase, setPhase] = useState<Phase>('intro');
  const [detected, setDetected] = useState<DetectedPart[]>([]);
  const [selectedPart, setSelectedPart] = useState<TrackingTarget | null>(null);
  const [progress, setProgress] = useState(0);
  const [cornerIdx, setCornerIdx] = useState(0);
  const [cornerSamples, setCornerSamples] = useState<Array<{ x: number; y: number }>>([]);
  const [testTargets, setTestTargets] = useState<Array<{ x: number; y: number; hit: boolean }>>([]);
  const [testIdx, setTestIdx] = useState(0);
  const [cursorPos, setCursorPos] = useState({ x: -100, y: -100 });
  const [statusText, setStatusText] = useState('');

  const handleRef = useRef<PoseTrackerHandle | null>(null);
  const sampleBufferRef = useRef<Array<{ normX: number; normY: number }>>([]);
  const detectionCountRef = useRef<Record<string, number>>({});
  const holdTimerRef = useRef(0);

  const speak = useCallback((text: string) => {
    aacSpeak(text, speechRate, speechVolume);
  }, [speechRate, speechVolume]);

  // Clean up tracker on unmount
  useEffect(() => {
    return () => { handleRef.current?.stop(); };
  }, []);

  // Listen for raw pose samples
  useEffect(() => {
    const handler = (e: Event) => {
      const detail = (e as CustomEvent).detail;
      if (detail?.normX != null) {
        sampleBufferRef.current.push({ normX: detail.normX, normY: detail.normY });
        if (sampleBufferRef.current.length > 100) sampleBufferRef.current.shift();
      }
    };
    window.addEventListener('prism-pose-sample', handler);
    return () => window.removeEventListener('prism-pose-sample', handler);
  }, []);

  // ── PHASE: Detection ──
  const startDetection = useCallback(() => {
    setPhase('detecting');
    setStatusText('Looking for you...');
    speak('Hold still. I am looking for you.');
    detectionCountRef.current = {};

    if (handleRef.current) handleRef.current.stop();

    const handle = startPoseTracker({
      dwellMs: 99999,
      sensitivity: 5,
      smoothing: 0.15,
      trackingTarget: 'nose',
      cursorSmoothing: 0.12,
      onMove(x, y) { setCursorPos({ x, y }); },
      onDwell() {},
      onStatusChange(status, activeTarget) {
        if (status === 'tracking' && activeTarget) {
          const counts = detectionCountRef.current;
          counts[activeTarget] = (counts[activeTarget] || 0) + 1;
        }
      },
    });
    handleRef.current = handle;

    // After 5 seconds, analyze which body parts were detected
    setTimeout(() => {
      const counts = detectionCountRef.current;
      const results: DetectedPart[] = [];
      for (const bp of BODY_PARTS) {
        const count = counts[bp.target] || 0;
        if (count > 5) {
          results.push({ ...bp, confidence: Math.min(100, Math.round(count / 1.5)) });
        }
      }
      results.sort((a, b) => b.confidence - a.confidence);
      setDetected(results);

      if (results.length > 0) {
        setSelectedPart(results[0].target);
        setStatusText(`Found: ${results.map(r => r.emoji).join(' ')}`);
        speak(`I can see your ${results[0].label}. Let's calibrate.`);
      } else {
        setStatusText('No body parts detected. Try moving closer.');
        speak('I cannot see you. Please move closer to the camera.');
      }
    }, 5000);
  }, [speak]);

  // ── PHASE: Calibrate Center ──
  const startCenterCalibration = useCallback(() => {
    setPhase('calibrate-center');
    sampleBufferRef.current = [];
    setProgress(0);
    setStatusText('Point to the center circle');
    speak('Point to the center of the screen. Hold still.');

    let elapsed = 0;
    const interval = setInterval(() => {
      elapsed += 100;
      setProgress(Math.min(1, elapsed / 3000));
      if (elapsed >= 3000) {
        clearInterval(interval);
        // Move to corners
        setCornerIdx(0);
        setCornerSamples([]);
        setPhase('calibrate-corners');
        setProgress(0);
        speak('Now point to the top left corner.');
        setStatusText('Point to the highlighted corner');
      }
    }, 100);

    return () => clearInterval(interval);
  }, [speak]);

  // ── PHASE: Calibrate Corners ──
  useEffect(() => {
    if (phase !== 'calibrate-corners') return;

    sampleBufferRef.current = [];
    let elapsed = 0;

    const interval = setInterval(() => {
      elapsed += 100;
      setProgress(Math.min(1, elapsed / 2500));

      if (elapsed >= 2500) {
        clearInterval(interval);

        // Average the samples from this corner
        const samples = sampleBufferRef.current;
        const avg = samples.length > 0
          ? {
              x: samples.reduce((s, v) => s + v.normX, 0) / samples.length,
              y: samples.reduce((s, v) => s + v.normY, 0) / samples.length,
            }
          : { x: 0.5, y: 0.5 };

        const newSamples = [...cornerSamples, avg];
        setCornerSamples(newSamples);

        if (cornerIdx < CORNER_TARGETS.length - 1) {
          setCornerIdx(cornerIdx + 1);
          setProgress(0);
          sampleBufferRef.current = [];
          const next = CORNER_TARGETS[cornerIdx + 1];
          speak(`Now point to ${next.label}.`);
        } else {
          // All corners captured — compute calibration
          const tl = newSamples[0];
          const tr = newSamples[1];
          const br = newSamples[2];
          const bl = newSamples[3];

          const mx = (v: number) => 1.0 - v; // mirror X for front camera
          const cal: PoseCalibrationData = {
            leftX: Math.min(mx(tl.x), mx(bl.x)),
            rightX: Math.max(mx(tr.x), mx(br.x)),
            topY: Math.min(tl.y, tr.y),
            bottomY: Math.max(bl.y, br.y),
          };

          // Ensure valid range
          if (cal.leftX >= cal.rightX) [cal.leftX, cal.rightX] = [cal.rightX, cal.leftX];
          if (cal.topY >= cal.bottomY) [cal.topY, cal.bottomY] = [cal.bottomY, cal.topY];

          savePoseCalibration(cal);
          speak('Calibration saved. Now lets test your accuracy.');

          // Generate test targets
          const targets = [];
          for (let i = 0; i < 5; i++) {
            targets.push({
              x: 15 + Math.random() * 70,
              y: 15 + Math.random() * 70,
              hit: false,
            });
          }
          setTestTargets(targets);
          setTestIdx(0);
          setPhase('accuracy-test');
          setStatusText('Tap the circles!');
        }
      }
    }, 100);

    return () => clearInterval(interval);
  }, [phase, cornerIdx, cornerSamples, speak]);

  // ── PHASE: Accuracy Test ──
  const handleTestHit = (idx: number) => {
    if (idx !== testIdx) return;
    tapFeedback();
    speak('Great!');
    setTestTargets(prev => prev.map((t, i) => i === idx ? { ...t, hit: true } : t));

    if (testIdx >= testTargets.length - 1) {
      // All targets hit
      setTimeout(() => {
        const hits = testTargets.filter(t => t.hit).length + 1; // +1 for this one
        speak(`Perfect! You hit ${hits} out of ${testTargets.length} targets.`);
        setPhase('complete');
      }, 500);
    } else {
      setTestIdx(testIdx + 1);
    }
  };

  // ── RENDER ──
  return (
    <div className="fixed inset-0 z-[10000] bg-[#0a0a1a] flex flex-col">
      {/* Header */}
      <div className="shrink-0 flex items-center justify-between px-6 py-4">
        <button onClick={onCancel} className="text-white/60 text-lg font-semibold">Cancel</button>
        <h1 className="text-white font-bold text-xl">
          {phase === 'intro' && 'Tracking Setup'}
          {phase === 'detecting' && 'Finding You...'}
          {phase === 'calibrate-center' && 'Step 1: Center'}
          {phase === 'calibrate-corners' && `Step 2: Corners (${cornerIdx + 1}/4)`}
          {phase === 'accuracy-test' && `Step 3: Test (${testIdx + 1}/${testTargets.length})`}
          {phase === 'complete' && 'Setup Complete!'}
        </h1>
        <div className="w-16" />
      </div>

      {/* Progress dots */}
      <div className="shrink-0 flex justify-center gap-2 pb-4">
        {['detecting', 'calibrate', 'test', 'done'].map((step, i) => (
          <div
            key={step}
            className={`w-3 h-3 rounded-full transition-all ${
              i <= ['detecting', 'calibrate-center', 'accuracy-test', 'complete'].indexOf(phase)
                ? 'bg-[#4CAF50] scale-125'
                : 'bg-white/20'
            }`}
          />
        ))}
      </div>

      {/* Main content */}
      <div className="flex-1 flex items-center justify-center relative overflow-hidden">

        {/* INTRO */}
        {phase === 'intro' && (
          <div className="text-center px-8 max-w-md">
            <div className="text-8xl mb-6">🎯</div>
            <h2 className="text-white text-3xl font-black mb-4">Let's Set Up Tracking</h2>
            <p className="text-white/70 text-lg mb-3">
              We'll find which body parts you can move, then calibrate the cursor to follow you.
            </p>
            <p className="text-white/50 text-sm mb-8">
              Make sure your camera can see you. This takes about 30 seconds.
            </p>
            <button
              onClick={() => { tapFeedback(); startDetection(); }}
              className="w-full py-4 rounded-2xl bg-[#4CAF50] text-white font-bold text-xl shadow-lg active:scale-95 transition-transform"
            >
              Start Setup
            </button>
          </div>
        )}

        {/* DETECTING */}
        {phase === 'detecting' && (
          <div className="text-center px-8">
            <div className="relative w-40 h-40 mx-auto mb-6">
              <div className="absolute inset-0 rounded-full border-4 border-[#4CAF50]/30 animate-ping" />
              <div className="absolute inset-4 rounded-full border-4 border-[#4CAF50]/50 animate-pulse" />
              <div className="absolute inset-0 flex items-center justify-center text-6xl">👁</div>
            </div>
            <p className="text-white text-xl font-bold mb-2">{statusText}</p>
            <p className="text-white/50">Move your hand, head, or body so I can see you</p>

            {detected.length > 0 && (
              <div className="mt-6 space-y-3">
                <p className="text-white/70 text-sm">Detected:</p>
                <div className="flex flex-wrap justify-center gap-2">
                  {detected.map(d => (
                    <button
                      key={d.target}
                      onClick={() => { tapFeedback(); setSelectedPart(d.target); }}
                      className={`px-4 py-3 rounded-2xl flex items-center gap-2 transition-all ${
                        selectedPart === d.target
                          ? 'bg-[#4CAF50] text-white scale-110 shadow-lg'
                          : 'bg-white/10 text-white/80'
                      }`}
                    >
                      <span className="text-2xl">{d.emoji}</span>
                      <span className="font-bold">{d.label}</span>
                      <span className="text-xs opacity-60">{d.confidence}%</span>
                    </button>
                  ))}
                </div>
                <button
                  onClick={() => {
                    tapFeedback();
                    if (selectedPart) {
                      useSettingsStore.getState().update({ cameraTrackingTarget: selectedPart });
                      startCenterCalibration();
                    }
                  }}
                  disabled={!selectedPart}
                  className="mt-4 w-full max-w-xs mx-auto py-3 rounded-2xl bg-[#4CAF50] text-white font-bold text-lg shadow-lg active:scale-95 transition-transform disabled:opacity-30"
                >
                  Calibrate {detected.find(d => d.target === selectedPart)?.label}
                </button>
              </div>
            )}
          </div>
        )}

        {/* CALIBRATE CENTER */}
        {phase === 'calibrate-center' && (
          <>
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="relative">
                <svg width="120" height="120" className="animate-pulse">
                  <circle cx="60" cy="60" r="55" fill="none" stroke="rgba(76,175,80,0.3)" strokeWidth="4" />
                  <circle
                    cx="60" cy="60" r="55"
                    fill="none" stroke="#4CAF50" strokeWidth="6"
                    strokeDasharray={345}
                    strokeDashoffset={345 * (1 - progress)}
                    strokeLinecap="round"
                    transform="rotate(-90 60 60)"
                  />
                </svg>
                <div className="absolute inset-0 flex items-center justify-center">
                  <div className="w-8 h-8 rounded-full bg-[#4CAF50] shadow-lg shadow-[#4CAF50]/50" />
                </div>
              </div>
            </div>
            <div className="absolute bottom-20 left-0 right-0 text-center">
              <p className="text-white text-lg font-bold">{statusText}</p>
              <p className="text-white/50 text-sm">Hold still for 3 seconds</p>
            </div>
          </>
        )}

        {/* CALIBRATE CORNERS */}
        {phase === 'calibrate-corners' && (
          <>
            {CORNER_TARGETS.map((corner, idx) => (
              <div
                key={idx}
                className={`absolute transition-all duration-500 ${idx === cornerIdx ? 'scale-100 opacity-100' : idx < cornerIdx ? 'scale-75 opacity-30' : 'scale-50 opacity-10'}`}
                style={{ left: `${corner.x}%`, top: `${corner.y}%`, transform: 'translate(-50%, -50%)' }}
              >
                {idx === cornerIdx ? (
                  <div className="relative">
                    <svg width="100" height="100">
                      <circle cx="50" cy="50" r="45" fill="none" stroke="rgba(33,150,243,0.3)" strokeWidth="4" />
                      <circle
                        cx="50" cy="50" r="45"
                        fill="none" stroke="#2196F3" strokeWidth="6"
                        strokeDasharray={283}
                        strokeDashoffset={283 * (1 - progress)}
                        strokeLinecap="round"
                        transform="rotate(-90 50 50)"
                      />
                    </svg>
                    <div className="absolute inset-0 flex items-center justify-center text-3xl">{corner.emoji}</div>
                  </div>
                ) : (
                  <div className={`w-12 h-12 rounded-full flex items-center justify-center ${idx < cornerIdx ? 'bg-[#4CAF50]' : 'bg-white/10'}`}>
                    <span className="text-xl">{idx < cornerIdx ? '✓' : corner.emoji}</span>
                  </div>
                )}
              </div>
            ))}
            <div className="absolute bottom-20 left-0 right-0 text-center">
              <p className="text-white text-lg font-bold">Point to {CORNER_TARGETS[cornerIdx]?.label}</p>
              <p className="text-white/50 text-sm">Hold for 2.5 seconds</p>
            </div>
          </>
        )}

        {/* ACCURACY TEST */}
        {phase === 'accuracy-test' && (
          <>
            {testTargets.map((target, idx) => (
              <button
                key={idx}
                onClick={() => handleTestHit(idx)}
                disabled={idx !== testIdx || target.hit}
                className={`absolute w-16 h-16 rounded-full transition-all duration-300 ${
                  target.hit
                    ? 'bg-[#4CAF50] scale-75 opacity-50'
                    : idx === testIdx
                      ? 'bg-[#FF6B6B] animate-pulse shadow-lg shadow-[#FF6B6B]/50 scale-110'
                      : 'bg-white/10 scale-75'
                }`}
                style={{
                  left: `${target.x}%`,
                  top: `${target.y}%`,
                  transform: 'translate(-50%, -50%)',
                }}
              >
                {target.hit ? <span className="text-2xl">✓</span> : idx === testIdx ? <span className="text-2xl">👆</span> : null}
              </button>
            ))}
            <div className="absolute bottom-20 left-0 right-0 text-center">
              <p className="text-white text-lg font-bold">{statusText}</p>
              <p className="text-white/50 text-sm">{testTargets.filter(t => t.hit).length}/{testTargets.length} hits</p>
            </div>
          </>
        )}

        {/* COMPLETE */}
        {phase === 'complete' && (
          <div className="text-center px-8 max-w-md">
            <div className="text-8xl mb-6 animate-bounce">🎉</div>
            <h2 className="text-white text-3xl font-black mb-4">All Set!</h2>
            <p className="text-white/70 text-lg mb-2">
              Tracking: {detected.find(d => d.target === selectedPart)?.emoji} {detected.find(d => d.target === selectedPart)?.label}
            </p>
            <p className="text-white/50 text-sm mb-8">
              The cursor will follow your movements. You can recalibrate anytime from Settings.
            </p>
            <button
              onClick={() => {
                tapFeedback();
                useSettingsStore.getState().update({ cameraInputEnabled: true });
                handleRef.current?.stop();
                onComplete();
              }}
              className="w-full py-4 rounded-2xl bg-[#4CAF50] text-white font-bold text-xl shadow-lg active:scale-95 transition-transform"
            >
              Start Using Prism AAC
            </button>
          </div>
        )}
      </div>

      {/* Status bar */}
      <div className="shrink-0 px-6 py-3 flex items-center justify-center gap-2">
        <div className={`w-2 h-2 rounded-full ${cursorPos.x > 0 ? 'bg-[#4CAF50]' : 'bg-[#FF9800]'}`} />
        <span className="text-white/40 text-xs">
          {cursorPos.x > 0 ? 'Camera active' : 'Waiting for camera...'}
        </span>
      </div>
    </div>
  );
}

