  });

  it('direct add when remote description already set', () => {
    const hasRemoteDesc = true;
    const pending: string[] = [];
    if (hasRemoteDesc) { /* add directly */ } else { pending.push('c1'); }
    expect(pending).toHaveLength(0);
  });
});

